// ── 일부 항목만 취소되고 나머지가 전부 배부완료됐는데도 상태가 "승인됨"에
// 갇혀있던 과거 데이터를 일괄 보정 (distributeItems의 이전 버그로 인한 데이터)
function fixStuckApprovedStatuses() {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();
  let fixedCount = 0;

  for (let i = 1; i < rows.length; i++) {
    if (!rows[i][0]) continue;
    const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    if (isOld) continue; // 구형 행은 대상 아님

    const itemsCol = 10, statusCol = 12, updatedCol = 13;
    const status = String(rows[i][statusCol] || '');
    if (status !== 'approved') continue;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) { continue; }

    const active = items.filter(item => !item.cancelled);
    const allDone = active.length > 0 && active.every(item => item.distributed);
    if (!allDone) continue;

    s.getRange(i + 1, statusCol + 1).setValue('distributed');
    s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));
    fixedCount++;
  }

  Logger.log(`갇힌 신청건 상태 보정 완료: ${fixedCount}건`);
  try { SpreadsheetApp.getUi().alert(`${fixedCount}건을 배부완료 상태로 보정했습니다.`); } catch (e) {}
  if (fixedCount > 0) { try { generateReport(); } catch (e) {} }
}

// ── 레거시 데이터 보정: status=distributed인데 항목에 distributed 플래그/실제배부수량이
// 없는 경우(실제배부수량 기능이 생기기 전에 처리된 건) 신청수량 그대로 받은 것으로 간주해 채워넣는다
function fixLegacyDistributedItems() {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();
  let fixedRows = 0;

  for (let i = 1; i < rows.length; i++) {
    if (!rows[i][0]) continue;
    const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    if (isOld) continue;

    const itemsCol = 10, statusCol = 12;
    const status = String(rows[i][statusCol] || '');
    if (status !== 'distributed') continue;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) { continue; }

    let changed = false;
    items.forEach(item => {
      if (item.cancelled) return;
      if (!item.distributed) { item.distributed = true; changed = true; }
      if (item.distributedQty === undefined || item.distributedQty === null) {
        item.distributedQty = item.qty;
        changed = true;
      }
    });

    if (changed) {
      s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
      fixedRows++;
    }
  }

  Logger.log(`레거시 배부완료 항목 보정 완료: ${fixedRows}건`);
  try { SpreadsheetApp.getUi().alert(`${fixedRows}건의 배부완료 신청에서 실제배부수량을 신청수량 기준으로 채워넣었습니다.`); } catch (e) {}
  if (fixedRows > 0) { try { generateReport(); } catch (e) {} }
}

// ── 시트 초기화 (최초 1회 실행) ──────────────────────────────
function initSheets() {
  const ss = openSS();

  // 계정 시트 (이메일 컬럼 추가)
  let s = ss.getSheetByName(SHEET_ACCT) || ss.insertSheet(SHEET_ACCT);
  if (s.getLastRow() === 0)
    s.appendRow(['이름', '비밀번호해시', '권한', '이메일', '가입일']);

  // 관리자 계정 자동 생성
  const rows = s.getDataRange().getValues();
  const exists = rows.some(r => r[0] === '관리자');
  if (!exists) {
    const hash = sha256('kakao1234');
    s.appendRow(['관리자', hash, 'admin', '', new Date().toLocaleString('ko-KR')]);
  }

  // 신청 시트 (이메일 컬럼 추가)
  s = ss.getSheetByName(SHEET_REQ) || ss.insertSheet(SHEET_REQ);
  if (s.getLastRow() === 0)
    s.appendRow(['ID', '신청일시', '본부', '팀', '이름', '연락처', '이메일', '사용처',
                 '수취예정일', '사용예정일', '제품목록(JSON)', '총수량', '상태', '처리일시', '관리자메모']);

  // 재고 시트
  s = ss.getSheetByName(SHEET_STK) || ss.insertSheet(SHEET_STK);
  if (s.getLastRow() === 0)
    s.appendRow(['제품번호', '제품명', '재고수량']);

  return '초기화 완료';
}

// ── 라우터 ────────────────────────────────────────────────────
function jsonOut_(obj) {
  return ContentService.createTextOutput(JSON.stringify(obj)).setMimeType(ContentService.MimeType.JSON);
}
function doPost(e) {
  let data;
  try { data = JSON.parse(e.postData.contents); }
  catch (parseErr) { return jsonOut_({ ok: false, error: '잘못된 요청입니다.' }); }
  let result;
  let session = null;
  try {
    const { action } = data;
    // 접근통제: 로그인 여부·역할·본인 신청 여부를 서버에서 확인한다 (checkAccess_ 참고)
    const gate = checkAccess_(action, data);
    if (!gate.ok) {
      auditLog_(action, gate.session, data, gate.result, 'deny');
      return jsonOut_(gate.result);
    }
    session = gate.session;

    if      (action === 'logout')        result = logout(data, session);
    else if (action === 'register')      result = register(data);
    else if (action === 'verifyEmail')   result = verifyEmail(data);
    else if (action === 'resendVerification') result = resendVerification(data);
    else if (action === 'login')         result = login(data);
    else if (action === 'findAccountByEmail')     result = findAccountByEmail(data);
    else if (action === 'requestPasswordReset')   result = requestPasswordReset(data);
    else if (action === 'resetPasswordWithToken') result = resetPasswordWithToken(data);
    else if (action === 'submitRequest') result = submitRequest(data);
    else if (action === 'mergeIntoRequest') result = mergeIntoRequest(data);
    else if (action === 'mergeRequests')    result = mergeRequests(data);
    else if (action === 'getRequests')   result = getRequests(data);
    else if (action === 'updateRequest') result = updateRequest(data);
    else if (action === 'updateRequestSchedule') result = updateRequestSchedule(data);
    else if (action === 'saveDispatchMemo')  result = saveDispatchMemo(data);
    else if (action === 'getStock')      result = getStock();
    else if (action === 'updateStock')   result = updateStock(data);
    else if (action === 'setProductBlocked') result = setProductBlocked(data);
    else if (action === 'syncStock')       result = syncStock();
    else if (action === 'approveItems')    result = approveItems(data);
    else if (action === 'updateItemQty')   result = updateItemQty(data);
    else if (action === 'returnDistributedQty') result = returnDistributedQty(data);
    else if (action === 'editDistributedQty') result = editDistributedQty(data);
    else if (action === 'addAdminItem')     result = addAdminItem(data);
    else if (action === 'saveDistLog')      result = saveDistLog(data);
    else if (action === 'distributeItems') result = distributeItems(data);
    else if (action === 'cancelRequest')   result = cancelRequest(data);
    else if (action === 'cancelItems')       result = cancelItems(data);
    else if (action === 'requestCancelItem') result = requestCancelItem(data);
    else if (action === 'confirmCancelItem') result = confirmCancelItem(data);
    else if (action === 'rejectCancelItem')  result = rejectCancelItem(data);
    else if (action === 'uploadReport')      result = uploadReport(data);
    else if (action === 'submitFeedback')    result = submitFeedback(data);
    else if (action === 'getFeedback')       result = getFeedback();
    else result = { ok: false, error: '알 수 없는 action' };

    // 신청/재고 상태를 바꾸는 액션 이후에는 배부현황 시트를 자동 갱신
    const REPORT_TRIGGER_ACTIONS = [
      'submitRequest', 'updateRequest', 'approveItems', 'distributeItems',
      'cancelRequest', 'cancelItems', 'confirmCancelItem', 'rejectCancelItem',
      'updateRequestSchedule', 'updateItemQty', 'mergeIntoRequest', 'mergeRequests', 'returnDistributedQty',
      'editDistributedQty', 'addAdminItem'
    ];
    // 신청 시트(SHEET_REQ)를 바꾸는 모든 액션 뒤에는 관리자용 getRequests 캐시를 비운다 —
    // 안 비우면 방금 한 조정이 최대 REQ_CACHE_TTL_SEC초 동안 화면에 반영 안 될 수 있다.
    const REQ_MUTATING_ACTIONS = REPORT_TRIGGER_ACTIONS.concat([
      'saveDispatchMemo', 'saveDistLog', 'uploadReport', 'requestCancelItem'
    ]);
    if (result && result.ok !== false && REQ_MUTATING_ACTIONS.includes(action)) {
      try { clearRequestsCache(); } catch (cacheErr) { Logger.log('캐시 초기화 실패: ' + cacheErr.message); }
    }
    // 재고 수치는 신청/배부/취소뿐 아니라 재고 직접수정·차단·재계산에서도 바뀐다
    if (result && result.ok !== false &&
        (REQ_MUTATING_ACTIONS.includes(action) || ['updateStock', 'setProductBlocked', 'syncStock'].includes(action))) {
      clearStockCache();
    }
    if (action === 'generateReport') {
      // 프런트에서 수동 새로고침 요청 시 직접 호출 가능 (이때는 바로 결과를 보여줘야 하므로 동기 실행)
      try { generateReport(); result = { ok: true }; }
      catch (reportErr) { result = { ok: false, error: reportErr.message }; }
    } else if (result && result.ok !== false && REPORT_TRIGGER_ACTIONS.includes(action)) {
      // 배부현황 시트 재생성 + 캘린더 재동기화는 무거운 작업이라 매 요청마다 동기로 실행하면
      // 사용자가 버튼 누를 때마다 느려짐. 응답은 즉시 돌려주고, 실제 갱신은 몇 초 뒤
      // 백그라운드 트리거에서 처리한다 (연속 클릭 시에도 트리거 1개로 합쳐짐).
      try { scheduleDeferredRefresh(); }
      catch (schedErr) { Logger.log('지연 갱신 예약 실패: ' + schedErr.message); }
    }
    // 활동 중인 사용자의 세션을 연장 (화면이 자동으로 백그라운드 갱신하는 요청 bg:true는 연장하지 않는다)
    if (session && action !== 'logout' && PUBLIC_ACTIONS.indexOf(action) < 0 && !data.bg && result && typeof result === 'object') {
      const refreshed = maybeRefreshSession_(session);
      if (refreshed) result.sessionToken = refreshed;
    }
  } catch(err) {
    result = { ok: false, error: err.message };
  }
  auditLog_(data && data.action, session, data, result);
  return jsonOut_(result);
}

function doGet() {
  return jsonOut_({ ok: true, msg: '카카오 배부시스템 API', authEnforced: isAuthEnforced_() });
}

// ============================================================
//  인증 · 세션 · 접근통제 (인공지능 업무 보안 지침 제6~8조 준용)
// ============================================================
// 로그인하면 서버가 서명된 세션 토큰을 발급하고, 이후 모든 요청은 이 토큰으로 사용자·역할을 확인한다.
// 클라이언트가 보낸 role / name / adminName 값은 토큰이 있는 요청에서는 더 이상 믿지 않는다.
//
// 전환 기간 안전장치: Script Properties의 AUTH_ENFORCED가 'true'일 때만 "토큰 없는 요청"을 거부한다.
// 배포 직후에는 꺼져 있어(기존 화면이 그대로 동작) 프런트를 먼저 올린 뒤 enableAuthEnforcement()로 켠다.
const AUTH_IDLE_SEC          = 30 * 60;      // 마지막 사용 후 30분이면 만료
const AUTH_MAX_SEC           = 6 * 60 * 60;  // 로그인 후 절대 6시간 (CacheService 최대 보관시간과 맞춤)
const AUTH_REFRESH_BELOW_SEC = 20 * 60;      // 남은 시간이 이보다 적을 때만 토큰을 새로 발급
const LOGIN_MAX_FAILS        = 5;            // 연속 실패 허용 횟수
const LOGIN_LOCK_SEC         = 15 * 60;      // 잠금 시간

const PUBLIC_ACTIONS = ['register', 'login', 'findAccountByEmail', 'requestPasswordReset', 'resetPasswordWithToken', 'verifyEmail', 'resendVerification'];
// 관리자만 실행할 수 있는 동작 (그 외 로그인 사용자 전용: getStock, getRequests, submitRequest, submitFeedback, logout)
const ADMIN_ONLY_ACTIONS = [
  'updateRequest', 'updateRequestSchedule', 'saveDispatchMemo', 'updateStock', 'setProductBlocked',
  'syncStock', 'generateReport', 'approveItems', 'updateItemQty', 'returnDistributedQty',
  'editDistributedQty', 'addAdminItem', 'distributeItems', 'mergeRequests',
  'confirmCancelItem', 'rejectCancelItem', 'getFeedback'
];
// 본인 신청만 다룰 수 있는 동작 → 신청 ID가 들어 있는 필드 이름 (관리자는 예외)
const OWNER_ACTION_ID_FIELD = {
  cancelRequest: 'id', cancelItems: 'id', requestCancelItem: 'id',
  saveDistLog: 'id', uploadReport: 'id', mergeIntoRequest: 'existingId'
};

function isAuthEnforced_() {
  try { return PropertiesService.getScriptProperties().getProperty('AUTH_ENFORCED') === 'true'; }
  catch (e) { return false; }
}
function enableAuthEnforcement() {
  PropertiesService.getScriptProperties().setProperty('AUTH_ENFORCED', 'true');
  Logger.log('서버 인증 강제: 켜짐');
  try { SpreadsheetApp.getUi().alert('서버 인증 강제를 켰습니다.\n\n이제 로그인(토큰) 없이 들어오는 요청은 모두 거부됩니다.\n이미 열려 있던 화면은 새로고침해야 합니다.'); } catch (e) {}
}
function disableAuthEnforcement() {
  PropertiesService.getScriptProperties().setProperty('AUTH_ENFORCED', 'false');
  Logger.log('서버 인증 강제: 꺼짐');
  try { SpreadsheetApp.getUi().alert('서버 인증 강제를 껐습니다. (비상용 — 토큰 없는 요청이 다시 허용됩니다)'); } catch (e) {}
}

// ── 비밀 값(서명 키, 비밀번호 후추) — 시트가 아니라 Script Properties에만 보관 ──
const _propMemo = {};
function getOrCreateSecret_(key) {
  if (_propMemo[key]) return _propMemo[key];
  const props = PropertiesService.getScriptProperties();
  let v = props.getProperty(key);
  if (!v) {
    const lock = LockService.getScriptLock();
    lock.waitLock(10000);
    try {
      v = props.getProperty(key);
      if (!v) {
        v = (Utilities.getUuid() + Utilities.getUuid() + Utilities.getUuid()).replace(/-/g, '');
        props.setProperty(key, v);
      }
    } finally { lock.releaseLock(); }
  }
  _propMemo[key] = v;
  return v;
}

function toHex_(bytes) { return bytes.map(b => ('0' + (b & 0xff).toString(16)).slice(-2)).join(''); }
function sha256Hex_(str) {
  return toHex_(Utilities.computeDigest(Utilities.DigestAlgorithm.SHA_256, String(str), Utilities.Charset.UTF_8));
}
function safeEqual_(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
}
function nowSec_() { return Math.floor(Date.now() / 1000); }
function normNameServer_(s) { return String(s || '').trim().replace(/\s+/g, ' '); }
function escapeHtml_(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

// ── 세션 토큰: base64url(JSON) + '.' + HMAC-SHA256 서명 (서버에 세션 저장소가 필요 없음) ──
function signBody_(body) {
  return Utilities.base64EncodeWebSafe(Utilities.computeHmacSha256Signature(body, getOrCreateSecret_('AUTH_SECRET')));
}
function issueSession_(user, prev) {
  const now = nowSec_();
  const i0 = prev ? prev.i0 : now;
  const payload = {
    n: user.name, r: user.role, e: user.email || '',
    j: prev ? prev.j : Utilities.getUuid(),
    i0: i0,
    x: Math.min(now + AUTH_IDLE_SEC, i0 + AUTH_MAX_SEC)
  };
  const body = Utilities.base64EncodeWebSafe(JSON.stringify(payload), Utilities.Charset.UTF_8);
  return body + '.' + signBody_(body);
}
function verifySession_(token) {
  if (!token || typeof token !== 'string') return null;
  const parts = token.split('.');
  if (parts.length !== 2) return null;
  if (!safeEqual_(signBody_(parts[0]), parts[1])) return null;
  let p;
  try { p = JSON.parse(Utilities.newBlob(Utilities.base64DecodeWebSafe(parts[0])).getDataAsString('UTF-8')); }
  catch (e) { return null; }
  const now = nowSec_();
  if (!p || !p.n || !p.x || !p.i0 || now > p.x || now > p.i0 + AUTH_MAX_SEC) return null;
  try {
    const cache = CacheService.getScriptCache();
    if (cache.get('rvj_' + p.j)) return null;                                   // 로그아웃된 토큰
    const rv = cache.get('rvu_' + sha256Hex_(p.n).slice(0, 32));                // 비밀번호 변경 이전에 발급된 토큰
    if (rv && p.i0 <= Number(rv)) return null;
  } catch (e) {}
  return { name: p.n, role: p.r, email: p.e || '', jti: p.j, i0: p.i0, x: p.x };
}
// 활동 중인 사용자는 만료 전에 토큰을 갱신해 준다(남은 시간이 충분하면 그대로 둔다).
function maybeRefreshSession_(sess) {
  const now = nowSec_();
  if (sess.x - now > AUTH_REFRESH_BELOW_SEC) return null;
  if (now >= sess.i0 + AUTH_MAX_SEC) return null;
  return issueSession_({ name: sess.name, role: sess.role, email: sess.email }, { i0: sess.i0, j: sess.jti });
}
function revokeSession_(sess) {
  if (!sess) return;
  try { CacheService.getScriptCache().put('rvj_' + sess.jti, '1', Math.max(60, Math.min(21600, sess.x - nowSec_()))); } catch (e) {}
}
function revokeUserSessions_(name) {
  try { CacheService.getScriptCache().put('rvu_' + sha256Hex_(name).slice(0, 32), String(nowSec_()), 21600); } catch (e) {}
}

// ── 요청 한 건에 대한 접근 검사 ─────────────────────────────────
// 반환: { ok:true, session } 또는 { ok:false, result }  (session이 있으면 data를 서버 기준으로 덮어쓴다)
function checkAccess_(action, data) {
  const sess = verifySession_(data.sessionToken);
  if (PUBLIC_ACTIONS.indexOf(action) >= 0) return { ok: true, session: sess };

  if (!sess) {
    if (isAuthEnforced_()) {
      return { ok: false, result: { ok: false, code: 'AUTH_REQUIRED', error: '로그인이 필요하거나 로그인이 만료되었습니다. 다시 로그인해주세요.' } };
    }
    return { ok: true, session: null }; // 전환 기간: 토큰 없는 기존 화면은 예전처럼 동작
  }

  const forbidden = msg => ({ ok: false, session: sess, result: { ok: false, code: 'FORBIDDEN', error: msg || '권한이 없습니다.' } });
  const isAdmin = sess.role === 'admin';

  if (ADMIN_ONLY_ACTIONS.indexOf(action) >= 0) {
    if (!isAdmin) return forbidden('관리자 권한이 필요합니다.');
    data.adminName = sess.name; // 관리자 이름은 클라이언트 값이 아니라 토큰 기준
  }
  const idField = OWNER_ACTION_ID_FIELD[action];
  if (idField && !isAdmin) {
    const owner = requestOwnerName_(data[idField]);
    if (owner === null || normNameServer_(owner) !== normNameServer_(sess.name)) {
      return forbidden('본인의 신청만 처리할 수 있습니다.');
    }
  }
  if (action === 'getRequests') { data.name = sess.name; data.role = sess.role; }
  if (action === 'submitRequest' && !isAdmin) data.name = sess.name;
  return { ok: true, session: sess };
}

// 신청 ID로 신청인 이름만 가볍게 조회 (전체 시트를 읽지 않고 A열 → 해당 행의 E열)
function requestOwnerName_(id) {
  if (id === undefined || id === null || id === '') return null;
  const s = sheet(SHEET_REQ);
  const last = s.getLastRow();
  if (last < 2) return null;
  const ids = s.getRange(2, 1, last - 1, 1).getValues();
  for (let i = 0; i < ids.length; i++) {
    if (String(ids[i][0]) === String(id)) return String(s.getRange(i + 2, 5).getValue());
  }
  return null;
}

function logout(data, sess) { revokeSession_(sess); return { ok: true }; }

// ── 비밀번호 규칙 (지침 제7조) — 프런트의 validatePasswordPolicy와 동일하게 유지 ──
function validatePasswordPolicy_(pw, name) {
  pw = String(pw || '');
  const kinds = [/[A-Za-z]/, /[0-9]/, /[^A-Za-z0-9]/].filter(re => re.test(pw)).length;
  const okLen = kinds >= 3 ? pw.length >= 8 : (kinds === 2 ? pw.length >= 10 : false);
  if (!okLen) return '비밀번호는 영문·숫자·특수문자를 모두 섞어 8자 이상, 또는 두 종류 이상을 섞어 10자 이상이어야 합니다.';
  const nm = normNameServer_(name);
  if (nm && pw.toLowerCase().indexOf(nm.toLowerCase()) >= 0) return '이름이 포함된 비밀번호는 사용할 수 없습니다.';
  const low = pw.toLowerCase();
  for (let i = 0; i + 2 < low.length; i++) {
    const c1 = low.charCodeAt(i), c2 = low.charCodeAt(i + 1), c3 = low.charCodeAt(i + 2);
    const isAlnum = c => (c >= 48 && c <= 57) || (c >= 97 && c <= 122);
    if (!(isAlnum(c1) && isAlnum(c2) && isAlnum(c3))) continue;
    if ((c2 - c1 === 1 && c3 - c2 === 1) || (c1 - c2 === 1 && c2 - c3 === 1) || (c1 === c2 && c2 === c3)) {
      return '3자리 이상 연속된 문자·숫자(예: abc, 123, 111)는 사용할 수 없습니다.';
    }
  }
  return '';
}

// ── 비밀번호 저장: 'v2$솔트$HMAC(후추+솔트, 클라이언트해시)' — 시트만 유출돼도 값만으로 로그인할 수 없다 ──
function passwordHashV2_(clientHash, salt) {
  const sig = Utilities.computeHmacSha256Signature(String(clientHash), getOrCreateSecret_('PW_PEPPER') + salt);
  return 'v2$' + salt + '$' + toHex_(sig);
}
function newPasswordRecord_(clientHash) {
  return passwordHashV2_(clientHash, Utilities.getUuid().replace(/-/g, ''));
}
function verifyPassword_(stored, clientHash) {
  stored = String(stored || '');
  if (stored.indexOf('v2$') === 0) {
    const parts = stored.split('$');
    if (parts.length !== 3) return false;
    return safeEqual_(passwordHashV2_(clientHash, parts[1]), stored);
  }
  return safeEqual_(stored, String(clientHash)); // 예전 형식(SHA-256) — 첫 로그인 때 v2로 바꾼다
}
// 새 화면은 평문 비밀번호(HTTPS)를 보낸다 — 서버가 규칙을 검사하고 직접 해시한다. 구버전 화면은 hash만 보낸다.
function clientHashFrom_(data) {
  if (data.password !== undefined && data.password !== null && data.password !== '') return sha256Hex_(data.password);
  return String(data.hash || '');
}
const CLIENT_OUTDATED = { ok: false, code: 'CLIENT_OUTDATED', error: '화면이 오래되었습니다. 새로고침(Cmd/Ctrl + Shift + R) 후 다시 시도해주세요.' };

// ── 로그인 실패 잠금 (지침 제8조③) ───────────────────────────────
function loginFailKey_(name) { return 'lf_' + sha256Hex_(String(name)).slice(0, 32); }
function isLoginLocked_(name) {
  try { return Number(CacheService.getScriptCache().get(loginFailKey_(name)) || 0) >= LOGIN_MAX_FAILS; }
  catch (e) { return false; }
}
function recordLoginFail_(name) {
  try {
    const cache = CacheService.getScriptCache();
    const k = loginFailKey_(name);
    cache.put(k, String((Number(cache.get(k)) || 0) + 1), LOGIN_LOCK_SEC);
  } catch (e) {}
}
function clearLoginFails_(name) {
  try { CacheService.getScriptCache().remove(loginFailKey_(name)); } catch (e) {}
}
// 같은 대상에게 짧은 시간에 메일이 반복 발송되는 것을 막는다(메일 폭탄 방지). true면 이번엔 건너뜀.
function rateLimited_(key, sec) {
  try {
    const cache = CacheService.getScriptCache();
    const k = 'rl_' + sha256Hex_(key).slice(0, 32);
    if (cache.get(k)) return true;
    cache.put(k, '1', sec);
  } catch (e) {}
  return false;
}

// ── 회원가입 (이메일 소유 확인 후 사용 가능) ─────────────────────
// 계정 시트 열: 0 이름, 1 비밀번호, 2 권한, 3 이메일, 4 가입일시, 5 재설정토큰, 6 재설정만료,
//               7 인증상태('N'=인증대기 / 'Y'=인증완료 / 빈칸=예전 계정·관리자가 직접 만든 계정=인증완료로 취급),
//               8 인증토큰, 9 인증만료
// @worldvision.or.kr 형식만 맞으면 아무 주소로나 가입할 수 있으므로, 그 주소로 보낸 메일의 링크를 눌러야 로그인할 수 있다.
const VERIFY_TTL_MS = 24 * 60 * 60 * 1000;
function sendVerificationMail_(email, name, token) {
  const url = `${APP_URL}?verifyToken=${encodeURIComponent(token)}`;
  MailApp.sendEmail({
    to: email,
    subject: '[카카오프렌즈 GIK] 가입 이메일 인증 안내',
    htmlBody: `
      <div style="font-family:sans-serif; line-height:1.7">
        <h2>✉️ 이메일 인증</h2>
        <p>안녕하세요, ${escapeHtml_(name)}님.<br>아래 링크를 누르면 가입이 완료됩니다. (24시간 이내에만 유효합니다)</p>
        <p><a href="${url}">${url}</a></p>
        <p style="color:#888; font-size:12px; margin-top:20px">본인이 가입한 적이 없다면 이 메일은 무시해주셔도 됩니다.</p>
      </div>`
  });
}
function register(data) {
  const nm = textField_('이름', data.name, 30, { required: true });
  if (nm.err) return { ok: false, error: nm.err };
  const name = nm.v;
  const email = String(data.email || '').trim();
  const hasPlain = data.password !== undefined && data.password !== null && data.password !== '';
  if (!hasPlain && isAuthEnforced_()) return CLIENT_OUTDATED;
  if (hasPlain) {
    const perr = validatePasswordPolicy_(data.password, name);
    if (perr) return { ok: false, error: perr };
  }
  const clientHash = clientHashFrom_(data);
  if (!name || !clientHash) return { ok: false, error: '이름과 비밀번호를 입력해주세요.' };
  if (email.length > 120 || !/^[^\s@<>"']+@worldvision\.or\.kr$/i.test(email))
    return { ok: false, error: 'worldvision.or.kr 메일로만 가입할 수 있습니다.' };

  const token = Utilities.getUuid();
  const expiresAt = String(Date.now() + VERIFY_TTL_MS);
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_ACCT);
    const rows = s.getDataRange().getValues();
    let existing = -1;
    for (let i = 1; i < rows.length; i++) { if (rows[i][0] === name) { existing = i; break; } }
    const record = [name, newPasswordRecord_(clientHash), 'team', email, new Date().toLocaleString('ko-KR'), '', '', 'N', token, expiresAt];
    if (existing >= 0) {
      // 아직 이메일 인증을 못 끝낸 같은 이름은 새로 가입하는 사람의 정보로 덮어쓴다(이름 선점으로 본인이 못 가입하는 것을 막음)
      if (String(rows[existing][7]) !== 'N') return { ok: false, error: `"${name}" 이름으로 이미 가입된 계정이 있습니다.` };
      s.getRange(existing + 1, 1, 1, record.length).setValues([record]);
    } else {
      s.appendRow(record);
    }
  } finally { lock.releaseLock(); }

  try { sendVerificationMail_(email, name, token); }
  catch (e) {
    Logger.log('인증 메일 발송 실패: ' + e.message);
    return { ok: false, pendingVerification: true, error: '가입 정보는 저장되었지만 인증 메일을 보내지 못했습니다. 잠시 후 로그인 화면에서 "인증 메일 다시 받기"를 눌러주세요.' };
  }
  return { ok: false, pendingVerification: true, error: `${email} 로 인증 메일을 보냈습니다. 메일의 링크를 누르면 가입이 완료됩니다. (24시간 이내)` };
}

// 인증 메일의 링크를 눌렀을 때
function verifyEmail({ token }) {
  if (!token) return { ok: false, error: '잘못된 인증 링크입니다.' };
  const s = sheet(SHEET_ACCT);
  const rows = s.getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][7]) !== 'N' || String(rows[i][8] || '') !== String(token)) continue;
    if (!rows[i][9] || Date.now() > Number(rows[i][9])) {
      return { ok: false, error: '인증 링크가 만료되었습니다. 로그인 화면에서 "인증 메일 다시 받기"를 눌러주세요.' };
    }
    s.getRange(i + 1, 8).setValue('Y');
    s.getRange(i + 1, 9).setValue('');
    s.getRange(i + 1, 10).setValue('');
    return { ok: true, name: rows[i][0] };
  }
  return { ok: false, error: '유효하지 않거나 이미 사용된 인증 링크입니다. 이미 인증하셨다면 로그인해주세요.' };
}

// 인증 메일 다시 받기 — 계정 존재 여부와 상관없이 같은 응답, 1분에 한 번만
function resendVerification({ name }) {
  const GENERIC = { ok: true, msg: '인증 대기 중인 계정이면 인증 메일을 다시 보냈습니다.' };
  const nm = cleanText_(name).slice(0, 30);
  if (!nm) return { ok: false, error: '이름을 입력해주세요.' };
  if (rateLimited_('ver:' + nm, 60)) return GENERIC;
  const s = sheet(SHEET_ACCT);
  const rows = s.getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (rows[i][0] !== nm || String(rows[i][7]) !== 'N') continue;
    const token = Utilities.getUuid();
    s.getRange(i + 1, 9).setValue(token);
    s.getRange(i + 1, 10).setValue(String(Date.now() + VERIFY_TTL_MS));
    try { sendVerificationMail_(String(rows[i][3]).trim(), nm, token); } catch (e) { Logger.log('인증 메일 재발송 실패: ' + e.message); }
    break;
  }
  return GENERIC;
}

// ── 로그인 ───────────────────────────────────────────────────
function login(data) {
  const name = cleanText_(data.name);
  const hasPlain = data.password !== undefined && data.password !== null && data.password !== '';
  if (!hasPlain && isAuthEnforced_()) return CLIENT_OUTDATED;
  const clientHash = clientHashFrom_(data);
  if (!name || !clientHash) return { ok: false, error: '이름과 비밀번호를 입력해주세요.' };

  const s = sheet(SHEET_ACCT);
  const rows = s.getDataRange().getValues();
  let idx = -1;
  for (let i = 1; i < rows.length; i++) { if (rows[i][0] === name) { idx = i; break; } }
  // 관리자 계정은 15분 잠금 규정에서 제외한다(관리자가 로그인하지 못해 업무가 멈추는 것을 막기 위함).
  // 대신 틀릴 때마다 1초씩 지연시켜 무차별 대입 속도를 늦춘다.
  const isAdminAcct = idx >= 0 && String(rows[idx][2]) === 'admin';

  if (!isAdminAcct && isLoginLocked_(name)) {
    return { ok: false, locked: true, error: '로그인에 여러 번 실패하여 잠시 잠겼습니다. 15분 뒤에 다시 시도해주세요.' };
  }
  // 계정이 없든 비밀번호가 틀리든 같은 문구·같은 실패 횟수 처리 — 계정 존재 여부를 알려주지 않는다
  if (idx < 0 || !verifyPassword_(rows[idx][1], clientHash)) {
    if (isAdminAcct) Utilities.sleep(1000);
    else recordLoginFail_(name);
    return { ok: false, error: '이름 또는 비밀번호가 올바르지 않습니다.' };
  }
  clearLoginFails_(name);
  if (String(rows[idx][7]) === 'N') {
    return { ok: false, code: 'UNVERIFIED', error: '이메일 인증이 아직 완료되지 않았습니다. 가입할 때 받은 인증 메일의 링크를 눌러주세요.' };
  }
  if (String(rows[idx][1]).indexOf('v2$') !== 0) {
    s.getRange(idx + 1, 2).setValue(newPasswordRecord_(clientHash)); // 예전 형식 → 솔트+후추 형식으로 자동 전환
  }
  const user = { name: rows[idx][0], role: rows[idx][2], email: rows[idx][3] || '' };
  return { ok: true, name: user.name, role: user.role, email: user.email, sessionToken: issueSession_(user) };
}

// ── 아이디(이름) 찾기 ────────────────────────────────────────
// 화면에는 계정 존재 여부를 알려주지 않고, 가입된 이메일로만 이름을 메일로 보낸다.
function findAccountByEmail({ email }) {
  const GENERIC = { ok: true, msg: '입력하신 이메일로 가입된 계정이 있으면 안내 메일을 보냈습니다.' };
  if (!email) return { ok: false, error: '이메일을 입력해주세요.' };
  const wanted = String(email).trim().toLowerCase();
  if (rateLimited_('fid:' + wanted, 60)) return GENERIC;
  const rows = sheet(SHEET_ACCT).getDataRange().getValues().slice(1);
  const names = rows.filter(r => String(r[3] || '').trim().toLowerCase() === wanted).map(r => r[0]);
  if (names.length > 0) {
    MailApp.sendEmail({
      to: String(email).trim(),
      subject: '[카카오프렌즈 GIK] 가입 계정(이름) 안내',
      htmlBody: `<div style="font-family:sans-serif; line-height:1.7">
        <h2>🔍 가입 계정 안내</h2>
        <p>이 이메일로 가입된 계정(로그인 이름)은 다음과 같습니다.</p>
        <p><b>${names.map(escapeHtml_).join(', ')}</b></p>
        <p style="color:#888; font-size:12px; margin-top:20px">본인이 요청하지 않았다면 이 메일은 무시해주셔도 됩니다.</p>
      </div>`
    });
  }
  return GENERIC;
}

// ── 비밀번호 재설정 요청 ───────────────────────────────────────
// 계정 존재 여부와 상관없이 같은 응답을 준다. 일치하는 계정이 있을 때만 메일이 나간다.
// 토큰/만료시각은 계정 시트의 6·7번째 열에 그때그때 채워 넣는다.
function requestPasswordReset({ name, email }) {
  const GENERIC = { ok: true, msg: '입력하신 정보와 일치하는 계정이 있으면 재설정 메일을 보냈습니다.' };
  name = cleanText_(name);
  if (!name || !email) return { ok: false, error: '이름과 이메일을 입력해주세요.' };
  const wantedEmail = String(email).trim().toLowerCase();
  if (rateLimited_('rst:' + name + '|' + wantedEmail, 60)) return GENERIC;

  const s = sheet(SHEET_ACCT);
  const rows = s.getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (rows[i][0] !== name) continue;
    if (String(rows[i][3] || '').trim().toLowerCase() !== wantedEmail) continue;

    const token = Utilities.getUuid();
    const expiresAt = Date.now() + 30 * 60 * 1000; // 30분
    s.getRange(i + 1, 6).setValue(token);
    s.getRange(i + 1, 7).setValue(String(expiresAt));

    const resetUrl = `${APP_URL}?resetToken=${encodeURIComponent(token)}`;
    MailApp.sendEmail({
      to: String(rows[i][3]).trim(),
      subject: '[카카오프렌즈 GIK] 비밀번호 재설정 안내',
      htmlBody: `
        <div style="font-family:sans-serif; line-height:1.7">
          <h2>🔑 비밀번호 재설정</h2>
          <p>안녕하세요, ${escapeHtml_(name)}님.<br>아래 링크를 눌러 새 비밀번호를 설정해주세요. (30분 이내에만 유효합니다)</p>
          <p><a href="${resetUrl}">${resetUrl}</a></p>
          <p style="color:#888; font-size:12px; margin-top:20px">본인이 요청하지 않았다면 이 메일은 무시해주셔도 됩니다.</p>
        </div>
      `
    });
    break;
  }
  return GENERIC;
}

// ── 비밀번호 재설정 실행(토큰 검증) ───────────────────────────
function resetPasswordWithToken(data) {
  const token = data.token;
  const hasPlain = data.password !== undefined && data.password !== null && data.password !== '';
  if (!hasPlain && isAuthEnforced_()) return CLIENT_OUTDATED;
  const clientHash = clientHashFrom_(data);
  if (!token || !clientHash) return { ok: false, error: '잘못된 요청입니다.' };

  const s = sheet(SHEET_ACCT);
  const rows = s.getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (!rows[i][5] || String(rows[i][5]) !== String(token)) continue;

    const expiresAt = Number(rows[i][6] || 0);
    if (!expiresAt || Date.now() > expiresAt) {
      return { ok: false, error: '재설정 링크가 만료되었습니다. 다시 요청해주세요.' };
    }
    if (hasPlain) {
      const perr = validatePasswordPolicy_(data.password, rows[i][0]);
      if (perr) return { ok: false, error: perr };
    }
    s.getRange(i + 1, 2).setValue(newPasswordRecord_(clientHash));
    s.getRange(i + 1, 6).setValue('');   // 토큰 소진(재사용 방지)
    s.getRange(i + 1, 7).setValue('');
    if (String(rows[i][7]) === 'N') {    // 등록한 이메일로 받은 링크로 재설정했으므로 이메일 소유가 확인됨
      s.getRange(i + 1, 8).setValue('Y');
      s.getRange(i + 1, 9).setValue('');
      s.getRange(i + 1, 10).setValue('');
    }
    revokeUserSessions_(rows[i][0]);     // 이전에 발급된 로그인 세션은 모두 무효화
    clearLoginFails_(rows[i][0]);
    return { ok: true, name: rows[i][0] };
  }
  return { ok: false, error: '유효하지 않은 재설정 링크입니다.' };
}

// ============================================================
//  입력 정리·검증 (인공지능 업무 보안 지침 제9조③④ 준용)
// ============================================================
// 사용자가 보낸 문자열은 저장하기 전에 항상 정리한다. (화면에서도 별도로 이스케이프한다 — 이중 방어)
//  - 제어문자 제거, < > 는 전각 문자로 바꿔 HTML 태그로 해석되지 않게 한다.
//  - 맨 앞이 = + - @ 이면 구글 시트가 수식으로 실행할 수 있으므로 전각 문자로 바꿔 무력화한다.
const LEAD_FULLWIDTH = { '=': '＝', '+': '＋', '-': '－', '@': '＠' };
function cleanText_(v, multiline) {
  let s = String(v === undefined || v === null ? '' : v);
  s = s.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '');
  s = multiline ? s.replace(/\r\n?/g, '\n') : s.replace(/[\r\n\t]+/g, ' ');
  s = s.replace(/</g, '＜').replace(/>/g, '＞').trim();
  if (s && LEAD_FULLWIDTH[s.charAt(0)]) s = LEAD_FULLWIDTH[s.charAt(0)] + s.slice(1);
  return s;
}
// 문자열 입력 검증: { v: 정리된 값 } 또는 { err: 오류 문구 }
function textField_(label, v, max, opts) {
  opts = opts || {};
  const s = cleanText_(v, opts.multiline);
  if (opts.required && !s) return { err: `${label}을(를) 입력해주세요.` };
  if (s.length > max) return { err: `${label}은(는) ${max}자 이내로 입력해주세요.` };
  return { v: s };
}
function isoDateOrEmpty_(v) {
  const s = String(v === undefined || v === null ? '' : v).trim();
  if (s === '') return { v: '' };
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? { v: s } : { err: '날짜 형식이 올바르지 않습니다.' };
}
const MAX_ITEM_QTY = 100000;
function intInRange_(v, min, max) {
  const n = Number(v);
  return (isFinite(n) && Math.floor(n) === n && n >= min && n <= max) ? n : null;
}
// 신청 물품 목록: 알려진 필드만 남기고(화면이 임의로 distributed/approved 같은 상태값을 심지 못하게) 값을 검증한다.
function sanitizeItems_(items) {
  if (!Array.isArray(items) || items.length === 0) return { err: '신청할 제품이 없습니다.' };
  if (items.length > 200) return { err: '한 번에 신청할 수 있는 제품 종류는 200개까지입니다.' };
  const out = [];
  for (let i = 0; i < items.length; i++) {
    const it = items[i];
    if (!it || typeof it !== 'object') return { err: '제품 정보가 올바르지 않습니다.' };
    const num = String(it.num === undefined || it.num === null ? '' : it.num).trim();
    if (!/^\d{1,4}$/.test(num)) return { err: '제품 번호가 올바르지 않습니다.' };
    const qty = intInRange_(it.qty, 1, MAX_ITEM_QTY);
    if (qty === null) return { err: `수량은 1 이상 ${MAX_ITEM_QTY.toLocaleString()} 이하의 정수로 입력해주세요.` };
    const nm = textField_('제품명', it.name, 150, { required: true }); if (nm.err) return nm;
    const dt = textField_('상세사업', it.detail, 300);                  if (dt.err) return dt;
    const price = Math.min(Math.max(Number(it.price) || 0, 0), 1e9);
    out.push({ num: num, name: nm.v, qty: qty, price: price, total: price * qty, detail: dt.v });
  }
  return { items: out };
}
function validateEmailField_(v) {
  const s = String(v === undefined || v === null ? '' : v).trim();
  if (s === '') return { v: '' };
  if (s.length > 120 || !/^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(s)) return { err: '이메일 형식이 올바르지 않습니다.' };
  return { v: s };
}
function validateSubmitInput_(d) {
  const f = {};
  const checks = [
    ['dept', '본부', 60, {}], ['team', '팀', 60, {}], ['name', '이름', 30, { required: true }],
    ['contact', '연락처', 40, {}], ['reason', '사용처', 300, { required: true }]
  ];
  for (let i = 0; i < checks.length; i++) {
    const c = checks[i];
    const r = textField_(c[1], d[c[0]], c[2], c[3]);
    if (r.err) return { ok: false, error: r.err };
    f[c[0]] = r.v;
  }
  const em = validateEmailField_(d.email);            if (em.err) return { ok: false, error: em.err };
  const pd = isoDateOrEmpty_(d.pickupDate);           if (pd.err) return { ok: false, error: '수취예정일 ' + pd.err };
  const ud = isoDateOrEmpty_(d.useDate);              if (ud.err) return { ok: false, error: '사용예정일 ' + ud.err };
  const it = sanitizeItems_(d.items);                 if (it.err) return { ok: false, error: it.err };
  return { ok: true, data: Object.assign({}, d, f, { email: em.v, pickupDate: pd.v, useDate: ud.v, items: it.items }) };
}

// ============================================================
//  접속·작업 로그 (지침 제12조: 1년 이상 보관, 부적절 행위 점검)
// ============================================================
// '접속로그' 시트에 로그인·가입·재설정과 모든 데이터 변경 동작, 그리고 권한 거부를 남긴다.
// 1년 이상 보관해야 하므로 이 시트의 행을 지우지 않는다. (웹앱은 접속 IP를 알 수 없어 IP는 기록되지 않는다)
const SHEET_AUDIT = '접속로그';
const AUDIT_SKIP_ACTIONS = ['getRequests', 'getStock']; // 조회는 변경이 없고 양이 많아 기록하지 않는다
function ensureAuditSheet_() {
  const ss = openSS();
  let s = ss.getSheetByName(SHEET_AUDIT);
  if (!s) {
    s = ss.insertSheet(SHEET_AUDIT);
    s.appendRow(['일시', '사용자', '권한', '동작', '대상', '결과', '비고']);
    s.getRange(1, 1, 1, 7).setBackground('#3C1E1E').setFontColor('#FEE500').setFontWeight('bold');
    s.getRange(1, 8).setValue('※ 보안 지침 제12조에 따라 1년 이상 보관 — 행을 삭제하지 마세요.');
    s.setFrozenRows(1);
    s.setColumnWidth(1, 150); s.setColumnWidth(7, 320);
    s.getRange('A:A').setNumberFormat('yyyy-mm-dd hh:mm:ss');
  }
  return s;
}
// kind: 'deny'(권한 거부) | 생략(처리 결과 기준)
function auditLog_(action, session, data, result, kind) {
  try {
    if (AUDIT_SKIP_ACTIONS.indexOf(action) >= 0) return;
    data = data || {};
    const attempted = cleanText_(data.name || '').slice(0, 60);
    const user = session ? session.name : (attempted || '(미로그인)');
    const role = session ? session.role : ((result && result.role) || '');
    const target = cleanText_(data.id || data.existingId || data.targetId || data.num || '').slice(0, 40);
    let outcome = '성공';
    if (kind === 'deny') outcome = '거부';
    else if (result && result.ok === false) outcome = result.pendingVerification ? '성공' : '실패';
    const note = cleanText_((result && (result.code || '')) + ' ' + ((result && result.error) || '')).slice(0, 120);
    // 로그인하지 않은 상태의 반복 실패·거부가 로그를 가득 채우지 않도록 같은 대상은 10초에 한 번만 기록한다
    if (!session && outcome !== '성공' && rateLimited_('audit:' + action + ':' + user, 10)) return;
    ensureAuditSheet_().appendRow([new Date(), user, role, action, target, outcome, note]);
  } catch (e) { Logger.log('접속로그 기록 실패: ' + e.message); }
}
// 메뉴용: 최근 7일 접속로그에서 이상 징후를 요약해 보여준다 (지침 제12조②)
function reviewAccessLog() {
  const s = openSS().getSheetByName(SHEET_AUDIT);
  if (!s || s.getLastRow() < 2) { try { SpreadsheetApp.getUi().alert('접속로그가 아직 없습니다.'); } catch (e) {} return; }
  const since = Date.now() - 7 * 24 * 3600 * 1000;
  const rows = s.getRange(2, 1, s.getLastRow() - 1, 7).getValues().filter(r => r[0] instanceof Date && r[0].getTime() >= since);
  const count = (arr, keyFn) => arr.reduce((m, r) => { const k = keyFn(r); m[k] = (m[k] || 0) + 1; return m; }, {});
  const fails = count(rows.filter(r => r[3] === 'login' && r[5] === '실패'), r => r[1]);
  const denies = count(rows.filter(r => r[5] === '거부'), r => r[3] + ' (' + r[1] + ')');
  const adminActs = count(rows.filter(r => r[2] === 'admin' && r[5] === '성공'), r => r[1]);
  const top = o => Object.keys(o).sort((a, b) => o[b] - o[a]).slice(0, 8).map(k => `  - ${k}: ${o[k]}건`).join('\n') || '  (없음)';
  const msg = `[최근 7일 접속로그 점검] 총 ${rows.length}건\n\n로그인 실패 많은 계정\n${top(fails)}\n\n권한 거부(비정상 접근 시도)\n${top(denies)}\n\n관리자 작업 건수\n${top(adminActs)}`;
  Logger.log(msg);
  try { SpreadsheetApp.getUi().alert(msg); } catch (e) {}
}

// ── 신청 제출 (신청 즉시 재고 차감) ──────────────────────────
function submitRequest(rawData) {
  const checked = validateSubmitInput_(rawData || {});
  if (!checked.ok) return { ok: false, error: checked.error };
  // 동시에 여러 명이 신청할 때 "재고 확인 → 차감" 사이에 끼어들어
  // 둘 다 통과해버리는 경쟁 상태(race condition)를 막기 위한 잠금
  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    return submitRequest_(checked.data);
  } finally {
    lock.releaseLock();
  }
}

function submitRequest_({ dept, team, name, contact, email, reason, pickupDate, useDate, items }) {
  // ── 재고 사전 검증 (서버에서 실시간 확인) ──────────────────
  const stockResult = getStock({ fresh: true });
  const blocked = [];
  const insufficient = [];
  items.forEach(item => {
    const num       = String(item.num).padStart(3, '0');
    const available = stockResult.stock[num]?.current ?? stockResult.stock[num] ?? 0;
    if (stockResult.stock[num]?.blocked) {
      blocked.push(item.name);
      return;
    }
    if (item.qty > available) {
      insufficient.push(`${item.name} (신청 ${item.qty}개 / 잔여 ${available}개)`);
    }
  });
  if (blocked.length > 0) {
    return {
      ok: false,
      error: '관리자에 의해 신청이 일시 중지된 품목이 포함되어 있습니다:\n' + blocked.join(', ')
    };
  }
  if (insufficient.length > 0) {
    return {
      ok: false,
      error: '재고 부족으로 신청할 수 없습니다:\n' + insufficient.join('\n')
    };
  }

  // ── 재고 충분 → 신청 저장 + 차감 ─────────────────────────
  const s = sheet(SHEET_REQ);
  const id = Date.now().toString();
  const totalQty = items.reduce((sum, i) => sum + i.qty, 0);
  const newRow = s.getLastRow() + 1;
  s.appendRow([
    id,
    new Date().toLocaleString('ko-KR'),
    dept, team, name, contact, email || '', reason,
    pickupDate || '', useDate || '',
    JSON.stringify(items),
    totalQty,
    'pending', '', ''
  ]);
  // 수취예정일/사용예정일 셀이 Date 타입으로 자동 변환되지 않도록 텍스트 서식 고정
  s.getRange(newRow, 9).setNumberFormat('@').setValue(formatDateOnly(pickupDate));
  s.getRange(newRow, 10).setNumberFormat('@').setValue(formatDateOnly(useDate));
  deductStockBatch(items, { reqId: id, name, reason: '신청 제출' });
  return { ok: true, id };
}

// ── 신청 목록 조회 ────────────────────────────────────────────
// ── 관리자용 getRequests 결과 캐시 ──────────────────────────────
// 신청 건수가 쌓일수록 관리자가 전체 시트를 매번 읽고 파싱하는 비용이 계속
// 커진다(45초 자동 새로고침 + 각종 액션 후 재조회가 겹쳐 특히 부담). 일반
// 유저는 이미 본인 행만 읽어서 가볍기 때문에 캐시는 관리자 응답에만 건다.
// CacheService 한 키당 100KB 제한이 있어 90KB 단위로 쪼개 저장한다.
const REQ_CACHE_PREFIX  = 'reqCacheV1_';
const REQ_CACHE_TTL_SEC = 30;
const REQ_CACHE_CHUNK   = 30000; // 글자 수 기준 — 한글은 글자당 3바이트라 100KB 제한을 넘지 않게 보수적으로

function getRequestsFromCache() {
  try {
    const cache = CacheService.getScriptCache();
    const metaStr = cache.get(REQ_CACHE_PREFIX + 'meta');
    if (!metaStr) return null;
    const meta = JSON.parse(metaStr);
    const keys = [];
    for (let i = 0; i < meta.chunks; i++) keys.push(REQ_CACHE_PREFIX + 'c' + i);
    const chunkMap = cache.getAll(keys);
    let combined = '';
    for (let i = 0; i < meta.chunks; i++) {
      const part = chunkMap[REQ_CACHE_PREFIX + 'c' + i];
      if (part === undefined || part === null) return null; // 일부 청크가 만료됐으면 캐시 무효 처리
      combined += part;
    }
    return JSON.parse(combined);
  } catch (e) {
    return null; // 캐시 읽기 실패는 그냥 새로 조회하면 되므로 에러를 던지지 않는다
  }
}
function setRequestsCache(reqs) {
  try {
    const cache = CacheService.getScriptCache();
    const json = JSON.stringify(reqs);
    const chunks = [];
    for (let i = 0; i < json.length; i += REQ_CACHE_CHUNK) chunks.push(json.slice(i, i + REQ_CACHE_CHUNK));
    const payload = {};
    chunks.forEach((c, i) => { payload[REQ_CACHE_PREFIX + 'c' + i] = c; });
    payload[REQ_CACHE_PREFIX + 'meta'] = JSON.stringify({ chunks: chunks.length });
    cache.putAll(payload, REQ_CACHE_TTL_SEC);
  } catch (e) {
    // 캐시 저장 실패해도 응답 자체는 이미 만들어졌으니 기능에는 지장 없음
  }
}
// 신청 시트를 바꾸는 액션 뒤에 호출해서 캐시를 즉시 비운다 — 그래야 그 직후
// 새로고침에서 방금 바뀐 내용이 캐시된 옛날 값 대신 바로 보인다.
function clearRequestsCache() {
  try {
    const cache = CacheService.getScriptCache();
    const keys = [REQ_CACHE_PREFIX + 'meta'];
    for (let i = 0; i < 100; i++) keys.push(REQ_CACHE_PREFIX + 'c' + i);
    cache.removeAll(keys);
  } catch (e) {}
}

function getRequests({ name, role, force }) {
  const isAdmin = role === 'admin';
  // 이름 비교 시 앞뒤/중복 공백을 무시(다른 곳과 동일 규칙)
  const norm = s => String(s || '').trim().replace(/\s+/g, ' ');
  const wantName = norm(name);
  // 캐시/전체 조회는 모든 신청을 담지만, 관리자가 아니면 응답에는 본인 신청만 실어 보낸다.
  const pick = list => isAdmin ? list : list.filter(r => norm(r.name) === wantName);

  if (!force) {
    const cached = getRequestsFromCache();
    if (cached) return { ok: true, requests: pick(cached) };
  }

  // 전체를 한 번에 읽는다 — 예전엔 비관리자가 내 행마다 getRange를 따로 불러(N+1회 호출)
  // 신청이 많은 사람일수록 오히려 느렸다. 한 번 읽어 공용 캐시에 넣어두면 다른 사용자도 같이 빨라진다.
  const sh = sheet(SHEET_REQ);
  const lastRow = sh.getLastRow();
  const rows = lastRow < 2 ? [] : sh.getRange(2, 1, lastRow - 1, sh.getLastColumn()).getValues();
  const reqs = [];

  rows.forEach(r => {
    if (!r[0]) return; // 빈 행 skip
    // 컬럼 자동 감지: 각 컬럼에서 JSON을 찾아서 위치 파악
    let itemsJson = '[]';
    let status    = '';
    let pickupDate = '';
    let useDate    = '';
    let totalQty   = 0;
    let updatedAt  = '';
    let adminNote  = '';
    let plannedDate = ''; // 배부일 (관리자가 실제 배분한 날짜)

    // r[8]이 JSON이면 구형(13열), r[10]이 JSON이면 신형(15열)
    const r8  = String(r[8]  || '').trim();
    const r10 = String(r[10] || '').trim();

    if (r8.startsWith('[') || r8.startsWith('{')) {
      // 구형
      itemsJson  = r8;
      totalQty   = r[9];
      status     = String(r[10] || '');
      updatedAt  = r[11];
      adminNote  = r[12];
    } else if (r10.startsWith('[') || r10.startsWith('{')) {
      // 신형
      pickupDate = r[8];
      useDate    = r[9];
      itemsJson  = r10;
      totalQty   = r[11];
      status     = String(r[12] || '');
      updatedAt  = r[13];
      adminNote  = r[14];
      plannedDate = r[15] || '';
    } else {
      // 어느 쪽도 JSON이 아닌 경우 — 시트에 수동으로 입력된 행일 가능성이 높음.
      // (제품 목록 JSON이 없어 관리자 화면에서 조용히 사라지는 것을 방지하기 위해 pending으로 노출)
      const colCount = r.filter(c => c !== '' && c !== null && c !== undefined).length;
      status = colCount >= 13 ? String(r[12] || '') : String(r[10] || '');
      if (!status) status = 'pending';
      Logger.log(`⚠️ 신청 행 형식 인식 실패 (제품 목록 JSON 없음) — ID:${r[0]}, 이름:${r[4]}. 시트에서 직접 입력된 행인지 확인 필요.`);
    }

    // status가 다섯 가지 정상값(pending/approved/distributed/rejected/cancelled) 중
    // 어느 것도 아니면(셀 손상·공백 등) 신청관리/배부이력 어느 탭에도 안 걸려 조용히
    // 사라지므로, 반드시 pending으로 되돌려 관리자 화면에 다시 노출시킨다.
    const KNOWN_STATUSES = ['pending', 'approved', 'distributed', 'rejected', 'cancelled'];
    if (!KNOWN_STATUSES.includes(status)) {
      Logger.log(`⚠️ 알 수 없는 상태값 감지 — ID:${r[0]}, 이름:${r[4]}, 상태:"${status}" → pending으로 노출`);
      status = 'pending';
    }

    let items = [];
    try { items = JSON.parse(itemsJson || '[]'); } catch(e) { items = []; }

    reqs.push({
      id: r[0], createdAt: r[1], dept: r[2], team: r[3], name: r[4],
      contact: r[5], email: r[6], reason: r[7],
      pickupDate: formatDateOnly(pickupDate),
      useDate: formatDateOnly(useDate),
      items, totalQty, status, updatedAt, adminNote,
      plannedDate: formatDateOnly(plannedDate),
      dispatchMemo: String(r[16] || '') // 관리자가 직접 적는 출고 메모(17열) — 구형 행엔 없어도 무방
    });
  });

  setRequestsCache(reqs);
  return { ok: true, requests: pick(reqs) };
}

// ── 출고메모(관리자가 직접 적는 자유 메모, 17열) 저장 ──
function saveDispatchMemo({ id, memo }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;
    s.getRange(i + 1, 17).setValue(cleanText_(memo).slice(0, 300));
    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 수취예정일 / 사용예정일 / 배부일 수정 ──
function updateRequestSchedule({ id, pickupDate, useDate, plannedDate }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    if (isOld) return { ok: false, error: '구형 신청 건은 수취예정일/사용예정일/배부일을 지원하지 않습니다.' };

    // 날짜 셀이 자동으로 Date 타입으로 바뀌지 않도록 텍스트 서식 고정 후 기록
    if (pickupDate !== undefined) {
      s.getRange(i + 1, 8 + 1).setNumberFormat('@').setValue(formatDateOnly(pickupDate)); // 열 8: 수취예정일
    }
    if (useDate !== undefined) {
      s.getRange(i + 1, 9 + 1).setNumberFormat('@').setValue(formatDateOnly(useDate));     // 열 9: 사용예정일
    }
    if (plannedDate !== undefined) {
      s.getRange(i + 1, 15 + 1).setNumberFormat('@').setValue(formatDateOnly(plannedDate)); // 열 15: 배부일
    }

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 신청 상태 변경 + 이메일 발송 ─────────────────────────────
function updateRequest({ id, status, adminNote }) {
  if (['pending', 'approved', 'rejected', 'distributed', 'cancelled'].indexOf(status) < 0) {
    return { ok: false, error: '올바르지 않은 상태 값입니다.' };
  }
  if (adminNote !== undefined) adminNote = cleanText_(adminNote, true).slice(0, 1000);
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    // 구형/신형 자동 감지
    const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol   = isOld ? 8  : 10;
    const statusCol  = isOld ? 10 : 12;
    const updatedCol = isOld ? 11 : 13;
    const noteCol    = isOld ? 12 : 14;

    s.getRange(i + 1, statusCol  + 1).setValue(status);
    s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));
    if (adminNote !== undefined) s.getRange(i + 1, noteCol + 1).setValue(adminNote);

    const items = JSON.parse(rows[i][itemsCol] || '[]');

    // 반려 시 재고 복구
    if (status === 'rejected') {
      items.forEach(item => restoreStock(item.num, item.qty, { reqId: id, name: rows[i][4], reason: '신청 반려' }));
    }

    // 이메일 발송
    const recipientEmail = rows[i][6];
    const requesterName  = rows[i][4];
    const dept           = rows[i][2];
    const team           = rows[i][3];
    const reason         = rows[i][7];

    if (recipientEmail && (status === 'approved' || status === 'rejected' || status === 'distributed')) {
      const emailItems = items.filter(item => !item.cancelled); // 취소 항목 제외
      sendNotificationEmail(recipientEmail, requesterName, dept, team, reason, emailItems.length > 0 ? emailItems : items, status, adminNote || '');
    }

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 이메일 발송 ───────────────────────────────────────────────
function sendNotificationEmail(to, name, dept, team, reason, items, status, adminNote) {
  const statusText = {
    approved:    '✅ 승인되었습니다',
    rejected:    '❌ 반려되었습니다',
    distributed: '📦 배부 완료되었습니다'
  }[status] || status;

  const statusColor = {
    approved:    '#00B894',
    rejected:    '#E17055',
    distributed: '#0984E3'
  }[status] || '#888';

  const itemRows = items.map(i =>
    `<tr style="border-bottom:1px solid #eee">
      <td style="padding:8px 12px">${i.name}</td>
      <td style="padding:8px 12px;text-align:center;font-weight:600">${i.qty}개</td>
    </tr>`
  ).join('');

  const adminNoteHtml = adminNote
    ? `<div style="background:#FFF3CD;border-radius:8px;padding:12px 16px;margin-top:16px;font-size:14px">
        💬 <b>관리자 메모:</b> ${adminNote}
       </div>`
    : '';

  const html = `
  <div style="font-family:'Apple SD Gothic Neo',sans-serif;max-width:560px;margin:0 auto">
    <div style="background:#3C1E1E;padding:24px 32px;border-radius:12px 12px 0 0">
      <h2 style="color:#FEE500;margin:0;font-size:20px">🐾 카카오프렌즈 배부시스템</h2>
    </div>
    <div style="background:#fff;padding:28px 32px;border:1px solid #eee;border-top:none">
      <p style="font-size:16px;font-weight:700;color:#1A1A1A">${name}님의 신청이</p>
      <p style="font-size:24px;font-weight:800;color:${statusColor};margin:8px 0 20px">${statusText}</p>

      <div style="background:#FAFAFA;border-radius:8px;padding:12px 16px;margin-bottom:20px;font-size:14px">
        <div style="margin-bottom:6px"><span style="color:#888">소속</span> &nbsp;<b>${dept} ${team}</b></div>
        <div><span style="color:#888">사용처</span> &nbsp;<b>${reason}</b></div>
      </div>

      <table style="width:100%;border-collapse:collapse;font-size:14px">
        <thead>
          <tr style="background:#3C1E1E">
            <th style="padding:10px 12px;text-align:left;color:#FEE500">제품명</th>
            <th style="padding:10px 12px;text-align:center;color:#FEE500">수량</th>
          </tr>
        </thead>
        <tbody>${itemRows}</tbody>
      </table>

      ${adminNoteHtml}

      <p style="font-size:12px;color:#aaa;margin-top:24px;border-top:1px solid #eee;padding-top:16px">
        본 메일은 카카오프렌즈 배부시스템에서 자동 발송되었습니다.
      </p>
    </div>
  </div>`;

  // 메일 발송 실패(잘못된 이메일 주소, 일일 발송 한도 초과 등)가 나면 안 되는 이유:
  // 이 함수가 호출되는 시점엔 이미 시트에 상태/배부 데이터가 저장된 뒤라, 여기서
  // 예외가 그대로 올라가면 실제로는 처리가 성공했는데도 화면에는 "서버 오류"로
  // 뜨는 오해를 만든다. 그래서 메일 발송 실패는 조용히 로그만 남기고 삼킨다.
  try {
    MailApp.sendEmail({
      to:      to,
      subject: `[카카오프렌즈 배부] ${name}님 신청이 ${statusText}`,
      htmlBody: html
    });
  } catch (e) {
    Logger.log(`알림 메일 발송 실패 (수신: ${to}, 상태: ${status}): ${e.message}`);
  }
}

// ── 재고 조회 ─────────────────────────────────────────────────
// ── 재고 조회 ─────────────────────────────────────────────────
// 재고 시트 구조: A=제품번호, B=제품명, C=현재재고(잔여), D=원래재고
// D열이 비어있으면 C열을 원래재고로 취급
const STOCK_CACHE_KEY = 'stockCacheV1';
const STOCK_CACHE_TTL_SEC = 20;
// 화면 표시용은 짧은 캐시를 쓰지만, 신청·병합처럼 재고를 검증하고 차감하는 서버 로직은
// 반드시 { fresh: true }로 시트를 직접 읽어야 한다(캐시가 낡았으면 초과 신청이 통과할 수 있음).
function getStock(opts) {
  if (!(opts && opts.fresh)) {
    try {
      const hit = CacheService.getScriptCache().get(STOCK_CACHE_KEY);
      if (hit) return JSON.parse(hit);
    } catch (e) {}
  }
  const rows = sheet(SHEET_STK).getDataRange().getValues().slice(1);
  const stock = {};
  rows.forEach(r => {
    if (!r[0]) return;
    const num = String(r[0]).padStart(3, '0');
    const current  = Number(r[2]) || 0;
    const original = Number(r[3]) || current; // D열 없으면 C열을 원래재고로
    const blocked  = String(r[5] || '').trim() === 'Y'; // F열: 신청차단(현장재고 불일치 등으로 관리자가 임시 차단)
    stock[num] = { current, original, blocked };
  });
  const result = { ok: true, stock };
  try { CacheService.getScriptCache().put(STOCK_CACHE_KEY, JSON.stringify(result), STOCK_CACHE_TTL_SEC); } catch (e) {}
  return result;
}
function clearStockCache() {
  try { CacheService.getScriptCache().remove(STOCK_CACHE_KEY); } catch (e) {}
}

// ── 품목별 신청 차단/해제 (관리자) ────────────────────────────
// 현장재고와 신청재고가 안 맞을 때, 확인될 때까지 해당 품목의 신규 신청만
// 막는다. 이미 제출된 신청이나 관리자의 "신청 외 물품 추가 지급"에는
// 영향을 주지 않는다 — 관리자는 실제 상황을 알고 하는 조치이므로.
function setProductBlocked({ num, blocked }) {
  const s = sheet(SHEET_STK);
  const rows = s.getDataRange().getValues();
  const paddedNum = String(num).padStart(3, '0');
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]).padStart(3, '0') === paddedNum) {
      s.getRange(i + 1, 6).setValue(blocked ? 'Y' : '');
      return { ok: true };
    }
  }
  return { ok: false, error: '제품을 찾을 수 없습니다.' };
}

// ── 재고 수정 (관리자 직접 수정) ──────────────────────────────
function updateStock({ num, qty }) {
  const s = sheet(SHEET_STK);
  const rows = s.getDataRange().getValues();
  const paddedNum = String(num).padStart(3, '0');
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]).padStart(3, '0') === paddedNum) {
      s.getRange(i + 1, 3).setValue(qty);
      // 원래재고(D열)가 비어있으면 함께 설정
      if (!rows[i][3]) s.getRange(i + 1, 4).setValue(qty);
      return { ok: true };
    }
  }
  return { ok: false, error: '제품을 찾을 수 없습니다.' };
}

// ── 재고 재계산 (구글시트 행 삭제 후 동기화) ──────────────────
// 활성 신청(pending/approved/distributed) 기준으로 현재재고를 재계산
function syncStock() {
  const s = sheet(SHEET_STK);
  const stockRows = s.getDataRange().getValues();

  // 활성 신청의 제품별 사용량 합산 (구형/신형 자동 감지)
  const reqRows = sheet(SHEET_REQ).getDataRange().getValues().slice(1);
  const usedQty = {};
  reqRows.forEach(r => {
    if (!r[0]) return;
    // r[8]이 JSON이면 구형(13열), 아니면 신형(15열)
    const isOld    = String(r[8]).trim().startsWith('[') || String(r[8]).trim().startsWith('{');
    const itemsCol = isOld ? 8  : 10;
    const statusCol= isOld ? 10 : 12;
    const status   = r[statusCol];
    if (['pending', 'approved', 'distributed'].includes(status)) {
      try {
        const items = JSON.parse(r[itemsCol] || '[]');
        items.forEach(item => {
          if (item.cancelled) return; // 취소된 항목 제외
          const n = String(item.num).padStart(3, '0');
          // 이미 배부완료된 항목은 신청수량(qty)이 아니라 실제 배부수량(distributedQty)을
          // 기준으로 삼는다 — distributedQty는 반품 시 이미 차감 반영되고, 관리자가
          // 신청수량을 초과해 정정한 경우(초과배부)에도 실제로 나간 만큼 정확히 반영된
          // 값이다. 예전에는 항상 qty만 써서, 초과배부 정정으로 재고에서 별도 차감한
          // 부분이 재계산할 때마다 사라지고 신청수량 기준으로 되돌아가버렸다.
          const base = item.distributed ? (item.distributedQty ?? item.qty) : item.qty;
          const net = Math.max(0, Number(base) || 0);
          usedQty[n] = (usedQty[n] || 0) + net;
        });
      } catch(e) {}
    }
  });

  // 잔여재고(C열) = 원래재고(D열) - 배분수량
  // 배분수량(E열) = 활성 신청 합산
  for (let i = 1; i < stockRows.length; i++) {
    if (!stockRows[i][0]) continue;
    const num = String(stockRows[i][0]).padStart(3, '0');

    // D열(원래재고) 없으면 C열 값을 원래재고로 저장
    const original = Number(stockRows[i][3]) || Number(stockRows[i][2]) || 0;
    if (!stockRows[i][3] && stockRows[i][2]) {
      s.getRange(i + 1, 4).setValue(original);
    }

    const used    = usedQty[num] || 0;
    // 초과배부로 실제 나간 양이 총재고를 넘으면 0으로 가리지 않고 마이너스 그대로
    // 남겨둔다 — 현장재고 불일치를 진단하려면(관리자페이지 "제품 목록"에도 그대로
    // 노출됨) 이 값이 0으로 감춰지면 안 된다.
    const current = original - used;

    s.getRange(i + 1, 3).setValue(current);  // C열: 잔여재고
    s.getRange(i + 1, 5).setValue(used);     // E열: 배분수량
  }
  return { ok: true, msg: '재고 재계산 완료' };
}

// 구글시트 메뉴에서 즉시 재고를 재계산할 때 사용 (반품 등 처리 후 자동 새로고침을
// 기다리지 않고 바로 확인하고 싶을 때)
function forceSyncStockFromMenu() {
  const result = syncStock();
  try { SpreadsheetApp.getUi().alert(result.msg || '재고 재계산 완료'); } catch (e) {}
}

// ── 재고 차감 / 복구 ──────────────────────────────────────────
function deductStock(num, qty, meta)  { adjustStock(num, -qty, meta); }
function restoreStock(num, qty, meta) { adjustStock(num, +qty, meta); }

// ── 변경이력 기록 ────────────────────────────────────────────
// 재고가 바뀌는 모든 지점(adjustStock/adjustStockAllowNegative)에서 공통으로 호출되어
// "언제, 어떤 신청 때문에, 왜, 얼마나" 바뀌었는지 별도 시트에 남긴다.
function ensureChangeLogSheet() {
  const ss = openSS();
  let s = ss.getSheetByName('변경이력');
  if (!s) {
    s = ss.insertSheet('변경이력');
    s.appendRow(['일시', '제품번호', '신청ID', '신청인', '변경사유', '증감', '변경후재고']);
    s.getRange(1, 1, 1, 7).setBackground('#3C1E1E').setFontColor('#FEE500').setFontWeight('bold');
    s.setFrozenRows(1);
    s.setColumnWidth(5, 220);
  }
  return s;
}
function logStockChange(meta, num, delta, afterQty) {
  if (!meta) return; // 사유가 없는 호출(예: 테스트)은 기록하지 않음
  try {
    const s = ensureChangeLogSheet();
    s.appendRow([
      new Date().toLocaleString('ko-KR'),
      String(num).padStart(3, '0'),
      meta.reqId || '',
      cleanText_(meta.name),
      cleanText_(meta.reason),
      (delta > 0 ? '+' : '') + delta,
      afterQty
    ]);
  } catch (e) {
    Logger.log('변경이력 기록 실패: ' + e.message);
  }
}
// 여러 건을 한 번에 기록 — appendRow를 N번 부르는 대신 한 번의 setValues로 몰아서 쓴다.
function logStockChangeBatch(rows) {
  if (!rows || rows.length === 0) return;
  try {
    const s = ensureChangeLogSheet();
    s.getRange(s.getLastRow() + 1, 1, rows.length, 7).setValues(rows);
  } catch (e) {
    Logger.log('변경이력 일괄 기록 실패: ' + e.message);
  }
}

function adjustStock(num, delta, meta) {
  const s = sheet(SHEET_STK);
  const rows = s.getDataRange().getValues();
  const paddedNum = String(num).padStart(3, '0');
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]).padStart(3, '0') === paddedNum) {
      const cur = Number(rows[i][2]) || 0;
      const next = cur + delta;
      if (next < 0) {
        // 재고보다 많이 차감되는 경우 — 배부현황 리포트(JSON 원본 기준)와 재고 시트가
        // 어긋나는 원인이 되므로 0으로 조용히 밀어넣지 않고 반드시 로그를 남긴다.
        Logger.log(`⚠️ 재고 음수 발생 방지: 제품 ${paddedNum} 현재 ${cur} + 변화량 ${delta} = ${next} → 0으로 조정. syncStock() 실행 권장.`);
      }
      const finalVal = Math.max(0, next);
      s.getRange(i + 1, 3).setValue(finalVal);
      logStockChange(meta, paddedNum, delta, finalVal);
      return;
    }
  }
}

// 신청 제출처럼 한 번에 여러 품목의 재고를 한꺼번에 줄여야 할 때 사용.
// 품목 수만큼 재고 시트를 반복해서 읽고/쓰는 대신 딱 한 번만 읽고 한 번만 쓴다.
// (신청은 LockService로 잠금을 건 채로 처리되는데, 품목마다 시트를 왕복하면 그만큼
// 잠금을 오래 붙들고 있어서 동시에 여러 명이 쓸 때 서로 기다리는 시간이 길어진다)
function deductStockBatch(items, meta) {
  if (!items || items.length === 0) return;
  const s = sheet(SHEET_STK);
  const rows = s.getDataRange().getValues();
  const rowIndexByNum = {};
  for (let i = 1; i < rows.length; i++) {
    if (!rows[i][0]) continue;
    rowIndexByNum[String(rows[i][0]).padStart(3, '0')] = i;
  }

  const changeLogRows = [];
  const now = new Date().toLocaleString('ko-KR');
  items.forEach(item => {
    const paddedNum = String(item.num).padStart(3, '0');
    const rowIdx = rowIndexByNum[paddedNum];
    if (rowIdx === undefined) return; // 재고 시트에 없는 제품번호는 건드리지 않음
    const cur = Number(rows[rowIdx][2]) || 0;
    const next = cur - Number(item.qty);
    if (next < 0) {
      Logger.log(`⚠️ 재고 음수 발생 방지: 제품 ${paddedNum} 현재 ${cur} - ${item.qty} = ${next} → 0으로 조정. syncStock() 실행 권장.`);
    }
    const finalVal = Math.max(0, next);
    rows[rowIdx][2] = finalVal; // 메모리상에서만 갱신, 실제 쓰기는 마지막에 한 번에
    // 품목마다 사유를 다르게 남기고 싶으면 item.__reason에 넣어두면 우선 사용됨(없으면 공통 meta.reason)
    changeLogRows.push([now, paddedNum, meta.reqId || '', cleanText_(meta.name), cleanText_(item.__reason || meta.reason || ''), '-' + item.qty, finalVal]);
  });

  // C열(잔여재고) 전체를 한 번에 다시 쓴다 — 바뀐 행만 골라 쓰는 것보다
  // 연속된 범위를 통째로 쓰는 게 API 호출 1번으로 끝나 훨씬 빠르다.
  const colValues = rows.slice(1).map(r => [r[2]]);
  s.getRange(2, 3, colValues.length, 1).setValues(colValues);
  logStockChangeBatch(changeLogRows);
}

// 관리자가 신청 수량을 직접 수정할 때 사용 — 재고 부족 상태를 감추지 않고
// 음수(마이너스 표시)까지 그대로 반영해 실제 부족분을 화면에서 바로 알 수 있게 한다
function adjustStockAllowNegative(num, delta, meta) {
  const s = sheet(SHEET_STK);
  const rows = s.getDataRange().getValues();
  const paddedNum = String(num).padStart(3, '0');
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]).padStart(3, '0') === paddedNum) {
      const cur = Number(rows[i][2]) || 0;
      const next = cur + delta;
      s.getRange(i + 1, 3).setValue(next);
      logStockChange(meta, paddedNum, delta, next);
      return next;
    }
  }
  return null;
}

function currentStockOf(num) {
  const paddedNum = String(num).padStart(3, '0');
  const rows = sheet(SHEET_STK).getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]).padStart(3, '0') === paddedNum) return Number(rows[i][2]) || 0;
  }
  return null;
}

// 관리자가 수량을 줄이면서 "다음에 배부"를 선택했을 때, 같은 신청인 앞으로
// 작업일로부터 한 달 뒤 수취예정일/사용예정일을 가진 신청을 새로 만든다.
function createFollowUpRequest({ dept, team, name, contact, email, originalReqId }, item) {
  const s = sheet(SHEET_REQ);
  const id = Date.now().toString();
  const followUp = new Date();
  followUp.setMonth(followUp.getMonth() + 1);
  const dateStr = Utilities.formatDate(followUp, 'Asia/Seoul', 'yyyy-MM-dd');

  const items = [{ num: item.num, name: item.name, qty: item.qty, price: item.price || 0 }];
  const newRow = s.getLastRow() + 1;
  s.appendRow([
    id, new Date().toLocaleString('ko-KR'),
    dept || '', team || '', name || '', contact || '', email || '',
    `[자동생성] 수량조정 이월 (원신청 ${originalReqId})`,
    dateStr, dateStr,
    JSON.stringify(items), item.qty,
    'pending', '', ''
  ]);
  s.getRange(newRow, 9).setNumberFormat('@').setValue(dateStr);
  s.getRange(newRow, 10).setNumberFormat('@').setValue(dateStr);
  deductStock(item.num, item.qty, {
    reqId: id, name,
    reason: `수량조정 이월 신청 생성(원신청 ${originalReqId}): ${item.name} +${item.qty}`
  });
  return id;
}

// 항목별 배부처리 중 일부 항목만 체크하고 나머지는 "다음 배부일로 이월"을 선택했을 때,
// 같은 신청인 앞으로 관리자가 지정한 새 날짜의 새 신청을 만든다. 이미 승인을 마친
// 항목이므로 재승인 없이 approved로 바로 시작하고, 재고는 원 신청에서 이미 예약된
// 것을 그대로 이어받으므로 다시 차감/복구하지 않는다(원 신청에서는 해당 항목을
// cancelled 처리해서 이중 집계를 막는다 — distributeItems에서 처리).
function createDeferredRequest({ dept, team, name, contact, email, reason, originalReqId }, items, newDate) {
  const s = sheet(SHEET_REQ);
  const id = Date.now().toString();
  const dateStr = formatDateOnly(newDate);

  const cleanItems = items.map(it => ({
    num: it.num, name: it.name, qty: it.qty, price: it.price || 0,
    detail: it.detail || '', approved: true
  }));
  const totalQty = cleanItems.reduce((s2, it) => s2 + (Number(it.qty) || 0), 0);
  const newRow = s.getLastRow() + 1;
  s.appendRow([
    id, new Date().toLocaleString('ko-KR'),
    dept || '', team || '', name || '', contact || '', email || '',
    (reason ? `${reason} ` : '') + `[자동생성] 배부 보류 이월 (원신청 ${originalReqId})`,
    dateStr, dateStr,
    JSON.stringify(cleanItems), totalQty,
    'approved', '', ''
  ]);
  s.getRange(newRow, 9).setNumberFormat('@').setValue(dateStr);
  s.getRange(newRow, 10).setNumberFormat('@').setValue(dateStr);
  return id;
}

// ── 신청 병합 ────────────────────────────────────────────────
// 수취예정일·사용예정일이 같은 기존 신청에 새 항목들을 합쳐 넣는다.
function mergeIntoRequest({ existingId, items }) {
  const cleaned = sanitizeItems_(items);
  if (cleaned.err) return { ok: false, error: cleaned.err };
  items = cleaned.items;
  const stockResult = getStock({ fresh: true });
  const blocked = [];
  const insufficient = [];
  items.forEach(item => {
    const num = String(item.num).padStart(3, '0');
    const available = stockResult.stock[num]?.current ?? 0;
    if (stockResult.stock[num]?.blocked) {
      blocked.push(item.name);
      return;
    }
    if (item.qty > available) {
      insufficient.push(`${item.name} (신청 ${item.qty}개 / 잔여 ${available}개)`);
    }
  });
  if (blocked.length > 0) {
    return { ok: false, error: '관리자에 의해 신청이 일시 중지된 품목이 포함되어 있습니다:\n' + blocked.join(', ') };
  }
  if (insufficient.length > 0) {
    return { ok: false, error: '재고 부족으로 합칠 수 없습니다:\n' + insufficient.join('\n') };
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_REQ);
    const rows = s.getDataRange().getValues();

    for (let i = 1; i < rows.length; i++) {
      if (String(rows[i][0]) !== String(existingId)) continue;

      const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
      if (isOld) return { ok: false, error: '구형 신청 건과는 합칠 수 없습니다.' };

      const itemsCol = 10, totalQtyCol = 11, statusCol = 12, updatedCol = 13;
      const status = String(rows[i][statusCol] || '');
      if (status === 'cancelled' || status === 'rejected' || status === 'distributed') {
        return { ok: false, error: '이미 처리 완료되었거나 취소된 신청과는 합칠 수 없습니다.' };
      }

      let existingItems = [];
      try { existingItems = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) {}

      items.forEach(newItem => {
        const match = existingItems.find(it =>
          String(it.num).padStart(3, '0') === String(newItem.num).padStart(3, '0') && !it.cancelled
        );
        if (match) {
          match.qty = (Number(match.qty) || 0) + Number(newItem.qty);
        } else {
          existingItems.push({
            num: newItem.num, name: newItem.name, qty: newItem.qty,
            price: newItem.price || 0, detail: newItem.detail || ''
          });
        }
      });

      items.forEach(item => { item.__reason = `신청 합치기: ${item.name} +${item.qty}`; });
      deductStockBatch(items, { reqId: existingId, name: rows[i][4], reason: '신청 합치기' });

      const activeTotal = existingItems.filter(it => !it.cancelled).reduce((s2, it) => s2 + (Number(it.qty) || 0), 0);
      s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(existingItems));
      s.getRange(i + 1, totalQtyCol + 1).setValue(activeTotal);
      s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

      return { ok: true, id: existingId };
    }
    return { ok: false, error: '기존 신청을 찾을 수 없습니다.' };
  } finally {
    lock.releaseLock();
  }
}

// ── 관리자 - 여러 신청 건을 기준 신청 하나로 합치기 ─────────────
// submitRequest 시점에 각 신청의 재고가 이미 차감돼 있으므로, 여기서는
// 재고를 다시 건드리지 않고 물품목록만 기준(target) 신청으로 모으는
// 순수 기록 정리다. 나머지(source) 신청들은 cancelled로 표시하되,
// cancelRequest()와 달리 재고를 복구하지 않는다(이미 target에 남아있으므로).
//
// 대기중/승인(사전) 신청끼리, 또는 배부완료 신청끼리만 합칠 수 있고 섞어서는
// 안 된다 — "합쳐진 신청의 상태"가 애매해지기 때문. 배부완료 건을 합칠 때는
// distributedQty·distLog(배부처 기록)까지 같이 합산/이관해야 실제 배부
// 기록이 유실되지 않는다.
function mergeRequests({ targetId, sourceIds, adminName }) {
  if (!targetId || !sourceIds || !sourceIds.length) {
    return { ok: false, error: '합칠 신청을 선택해주세요.' };
  }
  const ids = [...new Set(sourceIds.map(String))].filter(sid => sid !== String(targetId));
  if (ids.length === 0) return { ok: false, error: '기준 신청 외에 합칠 신청이 없습니다.' };

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_REQ);
    const rows = s.getDataRange().getValues();

    const rowIndexById = {};
    rows.forEach((r, i) => { if (r[0]) rowIndexById[String(r[0])] = i; });

    const isOld = r => String(r[8]).trim().startsWith('[') || String(r[8]).trim().startsWith('{');
    const itemsCol = 10, totalQtyCol = 11, statusCol = 12, updatedCol = 13, noteCol = 14;
    const PRE_STATUSES = ['pending', 'approved'];

    const targetIdx = rowIndexById[String(targetId)];
    if (targetIdx === undefined) return { ok: false, error: '기준 신청을 찾을 수 없습니다.' };
    if (isOld(rows[targetIdx])) return { ok: false, error: '구형 신청 건은 합칠 수 없습니다.' };

    const targetStatus = String(rows[targetIdx][statusCol] || '');
    const isPreDistribution = PRE_STATUSES.includes(targetStatus);
    const isDistributed = targetStatus === 'distributed';
    if (!isPreDistribution && !isDistributed) {
      return { ok: false, error: '기준 신청은 대기중·승인·배부완료 상태여야 합칠 수 있습니다.' };
    }

    let targetItems = [];
    try { targetItems = JSON.parse(rows[targetIdx][itemsCol] || '[]'); } catch (e) {}
    // 대기중/승인인데 이미 일부 항목만 배부된(부분배부) 애매한 상태는 막는다.
    if (isPreDistribution && targetItems.some(it => it.distributed)) {
      return { ok: false, error: '이미 일부 배부된 신청은 합칠 수 없습니다.' };
    }

    // 먼저 전체 검증부터 마친 뒤에 시트를 쓴다(중간에 실패하면 일부만 합쳐지는 것을 방지).
    const sourceItemsById = {};
    for (const sid of ids) {
      const idx = rowIndexById[sid];
      if (idx === undefined) return { ok: false, error: `신청(${sid})을 찾을 수 없습니다.` };
      if (isOld(rows[idx])) return { ok: false, error: '구형 신청 건은 합칠 수 없습니다.' };

      const status = String(rows[idx][statusCol] || '');
      if (isPreDistribution && !PRE_STATUSES.includes(status)) {
        return { ok: false, error: `대기중/승인 신청과는 같은 상태의 신청만 합칠 수 있습니다 (${rows[idx][4]}).` };
      }
      if (isDistributed && status !== 'distributed') {
        return { ok: false, error: `배부완료 신청과는 배부완료 상태인 신청만 합칠 수 있습니다 (${rows[idx][4]}).` };
      }

      let items = [];
      try { items = JSON.parse(rows[idx][itemsCol] || '[]'); } catch (e) {}
      if (isPreDistribution && items.some(it => it.distributed)) {
        return { ok: false, error: `이미 일부 배부된 신청(${rows[idx][4]})은 합칠 수 없습니다.` };
      }
      sourceItemsById[sid] = items;
    }

    ids.forEach(sid => {
      const items = sourceItemsById[sid];
      items.filter(it => !it.cancelled).forEach(newItem => {
        const match = targetItems.find(it =>
          String(it.num).padStart(3, '0') === String(newItem.num).padStart(3, '0') && !it.cancelled
        );
        if (match) {
          match.qty = (Number(match.qty) || 0) + Number(newItem.qty);
          if (isDistributed) {
            // 배부완료 건을 합칠 때는 실제 배부수량·배부처 기록(distLog)까지 같이 합산해야
            // "실제로 몇 개를 누구에게 줬는지"가 유실되지 않는다.
            const matchDist = Number(match.distributedQty ?? match.qty) || 0;
            const newDist   = Number(newItem.distributedQty ?? newItem.qty) || 0;
            match.distributedQty = matchDist + newDist;
            match.distributed = true;
            if (!match.distributeDate && newItem.distributeDate) match.distributeDate = newItem.distributeDate;
            if (newItem.distLog && newItem.distLog.length) {
              match.distLog = (match.distLog || []).concat(newItem.distLog).slice(0, 10);
            }
          }
        } else {
          // 새 품목: 배부 관련 필드(distributed/distributedQty/distLog 등) 포함해서 그대로 옮긴다.
          targetItems.push({ ...newItem });
        }
      });

      const idx = rowIndexById[sid];
      s.getRange(idx + 1, statusCol + 1).setValue('cancelled');
      // 기존 관리자메모(결과보고 파일 링크 등)를 덮어쓰지 않고 뒤에 이어 붙인다 —
      // 이미 결과보고를 등록한 배부완료 건을 합칠 때 그 링크가 사라지면 안 되므로.
      const mergeNote = `⚑ ${adminName || '관리자'}가 신청 #${targetId}(으)로 합침`;
      const existingNote = String(rows[idx][noteCol] || '');
      s.getRange(idx + 1, noteCol + 1).setValue(existingNote ? existingNote + '\n' + mergeNote : mergeNote);
      s.getRange(idx + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));
    });

    const activeTotal = targetItems.filter(it => !it.cancelled).reduce((sum, it) => sum + (Number(it.qty) || 0), 0);
    s.getRange(targetIdx + 1, itemsCol + 1).setValue(JSON.stringify(targetItems));
    s.getRange(targetIdx + 1, totalQtyCol + 1).setValue(activeTotal);
    s.getRange(targetIdx + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

    return { ok: true, id: targetId };
  } finally {
    lock.releaseLock();
  }
}

// ── 관리자 - 신청 항목 수량 직접 수정 ─────────────────────────
// 수량이 줄면 그만큼 재고 복구, 늘면 그만큼 재고 추가 차감.
// 결과 재고가 0 이하가 되면 stockWarning:true 로 알려 프런트에서 경고 팝업을 띄우게 한다.
function updateItemQty({ id, idx, qty, adminName, deferReduced }) {
  const q = intInRange_(qty, 0, MAX_ITEM_QTY);
  if (q === null) return { ok: false, error: '올바른 수량을 입력하세요.' };
  qty = q;

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_REQ);
    const rows = s.getDataRange().getValues();

    for (let i = 1; i < rows.length; i++) {
      if (String(rows[i][0]) !== String(id)) continue;

      const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
      if (isOld) return { ok: false, error: '구형 신청 건은 수량 수정을 지원하지 않습니다.' };

      const itemsCol = 10, totalQtyCol = 11, updatedCol = 13;
      let items = [];
      try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) {}

      if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };
      if (items[idx].cancelled)   return { ok: false, error: '취소된 항목은 수량을 수정할 수 없습니다.' };
      if (items[idx].distributed) return { ok: false, error: '이미 배부된 항목은 수량을 수정할 수 없습니다.' };

      const oldQty = Number(items[idx].qty) || 0;
      const delta  = qty - oldQty; // 늘어난 만큼 재고 추가 차감(음수), 줄어든 만큼 재고 복구(양수)
      const productNum  = items[idx].num;
      const productName = items[idx].name;
      const productPrice= items[idx].price || 0;

      let deferredReqId = null;
      if (delta < 0 && deferReduced) {
        // 줄어든 만큼 재고 복구 후, 같은 신청인 앞으로 한 달 뒤 신청을 새로 만들어 이월
        const reducedAmt = -delta;
        adjustStockAllowNegative(productNum, reducedAmt, {
          reqId: id, name: rows[i][4],
          reason: `수량 감소분 이월(${adminName || '관리자'}): ${productName} -${reducedAmt} → 다음 신청으로`
        });
        deferredReqId = createFollowUpRequest({
          dept: rows[i][2], team: rows[i][3], name: rows[i][4],
          contact: rows[i][5], email: rows[i][6], originalReqId: id
        }, { num: productNum, name: productName, qty: reducedAmt, price: productPrice });
      } else {
        adjustStockAllowNegative(productNum, -delta, {
          reqId: id, name: rows[i][4],
          reason: `수량 수정(${adminName || '관리자'}): ${productName} ${oldQty}→${qty}`
        });
      }

      items[idx].qty = qty;
      const activeTotal = items.filter(it => !it.cancelled).reduce((s2, it) => s2 + (Number(it.qty) || 0), 0);

      s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
      s.getRange(i + 1, totalQtyCol + 1).setValue(activeTotal);
      s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

      const newStock = currentStockOf(productNum);
      return {
        ok: true,
        newStock,
        stockWarning: newStock !== null && newStock <= 0,
        productName,
        deferredReqId
      };
    }
    return { ok: false, error: '신청을 찾을 수 없습니다.' };
  } finally {
    lock.releaseLock();
  }
}

// ── 배부완료 후 반품 처리 ────────────────────────────────────
// 이미 배부된 항목이라도 일부(또는 전부)가 반품되는 경우, 반품수량만큼
// 실제배부수량을 줄이고 그만큼 재고를 복구한다. 신청수량(qty)은 원 신청 기록이므로 건드리지 않는다.
function returnDistributedQty({ id, idx, returnQty, adminName }) {
  returnQty = Number(returnQty);
  if (isNaN(returnQty) || returnQty <= 0) return { ok: false, error: '올바른 반품 수량을 입력하세요.' };

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_REQ);
    const rows = s.getDataRange().getValues();

    for (let i = 1; i < rows.length; i++) {
      if (String(rows[i][0]) !== String(id)) continue;

      const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
      if (isOld) return { ok: false, error: '구형 신청 건은 반품 처리를 지원하지 않습니다.' };

      const itemsCol = 10, updatedCol = 13;
      let items = [];
      try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) {}

      if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };
      if (!items[idx].distributed) return { ok: false, error: '아직 배부되지 않은 항목은 반품 처리할 수 없습니다.' };

      const currentDist = Number(items[idx].distributedQty ?? items[idx].qty) || 0;
      if (returnQty > currentDist) {
        return { ok: false, error: `반품 수량이 실제 배부수량(${currentDist}개)보다 많습니다.` };
      }

      const productNum  = items[idx].num;
      const productName = items[idx].name;

      items[idx].distributedQty = currentDist - returnQty;
      items[idx].returnedQty = (Number(items[idx].returnedQty) || 0) + returnQty;

      restoreStock(productNum, returnQty, {
        reqId: id, name: rows[i][4],
        reason: `반품 처리(${adminName || '관리자'}): ${productName} -${returnQty}`
      });

      s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
      s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

      return {
        ok: true,
        newStock: currentStockOf(productNum),
        remainingDistributed: items[idx].distributedQty,
        returnedTotal: items[idx].returnedQty
      };
    }
    return { ok: false, error: '신청을 찾을 수 없습니다.' };
  } finally {
    lock.releaseLock();
  }
}

// ── 배부완료 후 실배부수량 직접 수정(오기입 정정) ──────────────
// distributedQty는 표시/집계용 필드지만, 신청수량(qty)을 "초과"하는 부분은
// 신청 시점에 예약(차감)된 적이 없는 물량이라 재고에서 별도로 차감해야 한다 —
// distributeItems()의 초과배부 처리(adjustStockAllowNegative)와 동일한 원리다.
// 예) 신청 1400개 중 실제로는 1560개가 나간 경우, 신청수량만큼은 이미 차감돼
// 있으므로 초과분 160개만 추가로 차감한다(재고가 0 밑으로 내려가도 그대로 —
// 그게 바로 초과배부를 진단할 수 있게 해주는 부분). 이 정정을 여러 번 반복해도
// 중복 차감되지 않도록, "이전 초과분"과 "새 초과분"의 차이만큼만 조정한다.
function editDistributedQty({ id, idx, newQty, adminName }) {
  newQty = Number(newQty);
  if (isNaN(newQty) || newQty < 0) return { ok: false, error: '올바른 수량을 입력하세요.' };

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_REQ);
    const rows = s.getDataRange().getValues();

    for (let i = 1; i < rows.length; i++) {
      if (String(rows[i][0]) !== String(id)) continue;

      const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
      if (isOld) return { ok: false, error: '구형 신청 건은 지원하지 않습니다.' };

      const itemsCol = 10, updatedCol = 13;
      let items = [];
      try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) {}

      if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };
      if (!items[idx].distributed) return { ok: false, error: '아직 배부되지 않은 항목입니다.' };

      const reqQty      = Number(items[idx].qty) || 0;
      const productNum  = items[idx].num;
      const productName = items[idx].name;
      const oldQty = Number(items[idx].distributedQty ?? items[idx].qty) || 0;

      // 배부완료 항목은 실배부수량만큼 재고를 점유한다(syncStock과 같은 기준). 정정으로 수량이
      // 줄면 그 차이만큼 재고 복구(+), 늘면 추가 차감(−). 신청수량 이내에서의 조정도 포함된다.
      const stockDelta = oldQty - newQty;

      let newStock = currentStockOf(productNum);
      if (stockDelta !== 0) {
        newStock = adjustStockAllowNegative(productNum, stockDelta, {
          reqId: id, name: rows[i][4],
          reason: `실배부수량 정정(${adminName || '관리자'}): ${productName} ${oldQty}→${newQty}` +
                  (newQty > reqQty ? ` (신청 ${reqQty} 대비 초과 ${newQty - reqQty})` : '')
        });
      } else {
        logStockChange(
          { reqId: id, name: rows[i][4], reason: `실배부수량 정정(${adminName || '관리자'}): ${productName} ${oldQty}→${newQty}` },
          productNum, 0, newStock
        );
      }

      items[idx].distributedQty = newQty;
      s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
      s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

      return { ok: true, oldQty, newQty, newStock, stockWarning: newStock !== null && newStock <= 0 };
    }
    return { ok: false, error: '신청을 찾을 수 없습니다.' };
  } finally {
    lock.releaseLock();
  }
}

// ── 배부처 기록 (유저가 실제로 어디에 몇 개를 배부했는지 직접 기록) ──
// 재고/상태에는 영향 없이 items[idx].distLog 필드에만 저장하는 단순 기록용 기능.
function saveDistLog({ id, idx, distLog }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    if (isOld) return { ok: false, error: '구형 신청 건은 지원하지 않습니다.' };

    const itemsCol = 10, updatedCol = 13;
    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) {}

    if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };
    if (!items[idx].distributed) return { ok: false, error: '배부완료된 항목만 기록할 수 있습니다.' };

    const cleanLog = (Array.isArray(distLog) ? distLog : []).slice(0, 10)
      .map(e => ({
        dest: cleanText_(e && e.dest).slice(0, 100),
        qty: Math.min(Math.max(Math.floor(Number(e && e.qty) || 0), 0), 1000000)
      }))
      .filter(e => e.dest || e.qty);
    items[idx].distLog = cleanLog;

    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 신청하지 않은 물품을 관리자가 추가로 지급 ──────────────────
// 기존 신청 건에 원래 없던 항목을 새로 추가하고, 그 자리에서 바로 배부완료 처리한다.
// (신청 시점에 재고가 차감되는 다른 항목들과 달리, 이 항목은 지급 시점에 재고를 차감한다)
function addAdminItem({ id, num, name, price, qty, distributeDate, distributeMethod, adminName }) {
  const q = intInRange_(qty, 1, MAX_ITEM_QTY);
  if (q === null) return { ok: false, error: '올바른 수량을 입력하세요.' };
  qty = q;
  if (!num || !name) return { ok: false, error: '제품을 선택하세요.' };
  if (!/^\d{1,4}$/.test(String(num).trim())) return { ok: false, error: '제품 번호가 올바르지 않습니다.' };
  name = cleanText_(name).slice(0, 150);
  distributeMethod = cleanText_(distributeMethod).slice(0, 100);
  const dOk = isoDateOrEmpty_(distributeDate);
  distributeDate = dOk.err ? '' : dOk.v;

  const paddedNum = String(num).padStart(3, '0');
  const available = currentStockOf(paddedNum);
  if (available !== null && qty > available) {
    return { ok: false, error: `재고 부족: "${name}" 잔여 ${available}개` };
  }

  const lock = LockService.getScriptLock();
  lock.waitLock(10000);
  try {
    const s = sheet(SHEET_REQ);
    const rows = s.getDataRange().getValues();

    for (let i = 1; i < rows.length; i++) {
      if (String(rows[i][0]) !== String(id)) continue;

      const isOld = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
      if (isOld) return { ok: false, error: '구형 신청 건은 지원하지 않습니다.' };

      const itemsCol = 10, totalQtyCol = 11, statusCol = 12, updatedCol = 13;
      let items = [];
      try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch (e) {}

      items.push({
        num: paddedNum, name, price: Number(price) || 0, qty,
        approved: true, distributed: true, distributedQty: qty,
        distributeDate: distributeDate || formatDateOnly(new Date()),
        distributeMethod: distributeMethod || '',
        adminAdded: true
      });

      deductStock(paddedNum, qty, {
        reqId: id, name: rows[i][4],
        reason: `관리자 추가지급(${adminName || '관리자'}): ${name} +${qty}`
      });

      const activeItems = items.filter(it => !it.cancelled);
      const activeTotal = activeItems.reduce((s2, it) => s2 + (Number(it.qty) || 0), 0);

      s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
      s.getRange(i + 1, totalQtyCol + 1).setValue(activeTotal);
      s.getRange(i + 1, updatedCol + 1).setValue(new Date().toLocaleString('ko-KR'));

      // 이 지급으로 인해 신청 건의 활성 항목이 전부 배부완료 상태가 되면 상태를 올려준다.
      // 그 외의 경우(아직 미배부/미승인 항목이 남아있음)에는 기존 상태를 그대로 유지한다.
      const prevStatus = String(rows[i][statusCol] || '');
      const allDone = activeItems.length > 0 && activeItems.every(it => it.distributed);
      const newStatus = allDone ? 'distributed' : prevStatus;
      if (newStatus !== prevStatus) {
        s.getRange(i + 1, statusCol + 1).setValue(newStatus);
        const recipientEmail = rows[i][6];
        if (recipientEmail) {
          sendNotificationEmail(recipientEmail, rows[i][4], rows[i][2], rows[i][3], rows[i][7], activeItems, 'distributed', '');
          try {
            sendResultReportRequestEmail({
              email: recipientEmail, name: rows[i][4], reason: rows[i][7],
              useDate: formatDateOnly(rows[i][9])
            }, 'immediate');
          } catch (e) { Logger.log('결과보고 즉시안내 메일 발송 실패: ' + e.message); }
        }
      }

      return { ok: true, newStock: currentStockOf(paddedNum), status: newStatus };
    }
    return { ok: false, error: '신청을 찾을 수 없습니다.' };
  } finally {
    lock.releaseLock();
  }
}

// ── 이메일 테스트 (Apps Script에서 직접 실행해서 권한 승인) ────
// ── 재고 진단 (Apps Script에서 직접 실행해서 확인) ──────────────
function diagnoseStock() {
  const s = sheet(SHEET_STK);
  const rows = s.getDataRange().getValues();

  Logger.log('=== 재고 시트 진단 ===');
  Logger.log('총 행 수: ' + rows.length);
  Logger.log('헤더: ' + JSON.stringify(rows[0]));

  if (rows.length <= 1) {
    Logger.log('❌ 재고 시트에 데이터가 없습니다!');
    return;
  }

  // 첫 5개 행 확인
  Logger.log('--- 데이터 샘플 (첫 5행) ---');
  for (let i = 1; i <= Math.min(5, rows.length - 1); i++) {
    Logger.log(`행${i}: A열="${rows[i][0]}" B열="${rows[i][1]}" C열(현재재고)=${rows[i][2]} D열(원래재고)=${rows[i][3]}`);
  }

  // 002번 제품 찾기 테스트
  const testNum = '002';
  const found = rows.find(r => String(r[0]).padStart(3,'0') === testNum);
  if (found) {
    Logger.log(`✅ 002번 제품 발견: ${found[1]}, 현재재고=${found[2]}`);
  } else {
    Logger.log(`❌ 002번 제품을 찾지 못함. A열 값들: ${rows.slice(1,6).map(r=>r[0]).join(', ')}`);
  }
}

