// ── 재고 차감 직접 테스트 ────────────────────────────────────
// 002번 제품에서 1개 차감 → 시트에서 직접 확인
function testDeductStock() {
  Logger.log('=== 재고 차감 테스트 시작 ===');

  // 차감 전
  const before = getStock({ fresh: true }).stock['002'];
  Logger.log('차감 전 002번: ' + JSON.stringify(before));

  // 1개 차감
  adjustStock('002', -1);

  // 차감 후
  const after = getStock({ fresh: true }).stock['002'];
  Logger.log('차감 후 002번: ' + JSON.stringify(after));

  if (JSON.stringify(before) === JSON.stringify(after)) {
    Logger.log('❌ 차감 실패 - 값이 변하지 않음');
  } else {
    Logger.log('✅ 차감 성공! 구글시트 재고탭 C열 확인');
    // 원복
    adjustStock('002', +1);
    Logger.log('(테스트 후 원복 완료)');
  }
}

// ── 전체 진단 ────────────────────────────────────────────────
// ── 항목별 승인 처리 ──────────────────────────────────────────
function approveItems({ id, indices }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8 : 10;
    const statusCol= isOld ? 10 : 12;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) { items = []; }

    indices.forEach(idx => { if (items[idx] && !items[idx].cancelled) items[idx].approved = true; });

    // 취소된 항목은 제외하고, 나머지가 모두 승인되면 전체 승인
    const activeItems  = items.filter(item => !item.cancelled);
    const allApproved  = activeItems.length > 0 && activeItems.every(item => item.approved);
    const prevStatus   = String(rows[i][statusCol] || '');
    const newStatus    = allApproved ? 'approved' : prevStatus;

    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, statusCol + 1).setValue(newStatus);
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    // 전체 승인 완료 시 이메일 발송 (활성 항목만 포함)
    if (allApproved && prevStatus !== 'approved') {
      const recipientEmail = rows[i][6];
      if (recipientEmail) {
        sendNotificationEmail(recipientEmail, rows[i][4], rows[i][2], rows[i][3], rows[i][7], activeItems, 'approved', '');
      }
    }

    return { ok: true, status: newStatus };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 항목별 배부 처리 ──────────────────────────────────────────
function distributeItems({ id, distributedIndices, distributeDate, distributeMethod, dateMap, methodMap, qtyMap, pendingActionMap, deferDate, adminName }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8 : 10;
    const statusCol= isOld ? 10 : 12;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) { items = []; }

    // 이번에 체크 안 된(=보류) 항목 중 항목별로 "취소" 또는 "다음 배부일로 이월"이 지정된 것을 먼저 처리.
    // 이렇게 해야 남은 활성 항목이 전부 배부완료된 경우 신청 전체가 정상적으로 배부완료로 넘어간다.
    const deferredItems = [];
    if (pendingActionMap && typeof pendingActionMap === 'object') {
      Object.keys(pendingActionMap).forEach(key => {
        const idx = Number(key);
        const item = items[idx];
        if (!item || item.cancelled || item.distributed) return; // 이미 처리된 항목은 건드리지 않음
        if (distributedIndices.includes(idx)) return; // 체크된 항목은 대상 아님(방어적)
        const action = pendingActionMap[key];
        if (action === 'cancel') {
          item.cancelled = true;
          restoreStock(item.num, item.qty, { reqId: id, name: rows[i][4], reason: `배부 보류 항목 취소(${adminName || '관리자'})` });
        } else if (action === 'defer' && deferDate) {
          item.cancelled = true; // 원 신청에서는 제외하고 새 신청으로 이월
          deferredItems.push(item);
        }
      });
    }

    // 선택되지 않은 항목 → 재고 복구
    const stockWarnings = [];
    items.forEach((item, idx) => {
      if (item.cancelled) return; // 취소된 항목은 배부 대상에서 제외 (프런트에서 체크박스 자체가 없지만 방어적으로 한 번 더 확인)
      const wasDistributed = item.distributed || false;
      const willDistribute = distributedIndices.includes(idx);
      if (wasDistributed && !willDistribute) {
        // 이전에 배부됐는데 이번에 해제 → 복구 (재고는 신청수량 기준으로 예약되므로 신청수량만큼 복구)
        restoreStock(item.num, item.qty, { reqId: id, name: rows[i][4], reason: '배부 해제(재배정)' });
        delete item.distributedQty;
      }
      item.distributed = willDistribute;
      if (willDistribute) {
        // 항목별 날짜/방법 우선, 없으면 전체 공통값 사용
        const d = (dateMap   && dateMap[idx])   || distributeDate   || '';
        const m = (methodMap && methodMap[idx]) || distributeMethod || '';
        if (d) item.distributeDate   = d;
        if (m) item.distributeMethod = m;

        // 실제 배부수량 기록 — 신청수량보다 적게도, 많게도 지정할 수 있다.
        // 재고는 신청 시점에 신청수량(item.qty)만큼 이미 차감돼 있으므로(이미 배부된 항목을 다시
        // 저장하는 경우엔 직전에 반영된 실배부수량만큼), "예약돼 있던 양 − 이번 실배부수량"만큼만
        // 지금 재고에 반영한다. 적게 나갔으면 남는 만큼 복구(+), 많이 나갔으면 추가 차감(−).
        // 이 값이 syncStock()의 계산(배부완료 항목은 실배부수량 기준)과 같은 기준이라, 저장 직후
        // 재고 화면이 재계산 결과와 어긋나지 않는다. (예전에는 초과분만 반영하고 부족분은
        // 반영하지 않아서, 100개 신청에 0개 배부로 저장해도 재고가 복구되지 않았다.)
        const rawQty = (qtyMap && qtyMap[idx] !== undefined && qtyMap[idx] !== null && qtyMap[idx] !== '') ? Number(qtyMap[idx]) : item.qty;
        let distQty = rawQty;
        if (isNaN(distQty) || distQty < 0) distQty = item.qty;
        const reservedBefore = wasDistributed ? (Number(item.distributedQty ?? item.qty) || 0) : (Number(item.qty) || 0);
        const stockDelta = reservedBefore - distQty;
        if (stockDelta !== 0) {
          const newStock = adjustStockAllowNegative(item.num, stockDelta, {
            reqId: id, name: rows[i][4],
            reason: `배부수량 반영(${adminName || '관리자'}): ${item.name} 신청 ${item.qty} → 배부 ${distQty}` +
                    (stockDelta > 0 ? ` (미배부 ${stockDelta} 복구)` : ` (초과 ${-stockDelta} 추가차감)`)
          });
          if (stockDelta < 0 && newStock !== null && newStock <= 0) {
            stockWarnings.push({ productName: item.name, newStock });
          }
        }
        item.distributedQty = distQty;
      }
    });

    // 이월 대상 항목이 있으면 같은 신청인 앞으로 새 날짜의 새 신청을 만든다
    let deferredReqId = null;
    if (deferredItems.length > 0) {
      deferredReqId = createDeferredRequest({
        dept: rows[i][2], team: rows[i][3], name: rows[i][4],
        contact: rows[i][5], email: rows[i][6], reason: rows[i][7],
        originalReqId: id
      }, deferredItems, deferDate);
    }

    // 취소되지 않은 항목이 전부 배부됐으면 status=distributed, 일부만이면 approved 유지
    // (취소·이월 처리된 항목은 distributed가 될 수 없으므로 반드시 제외하고 판단해야 함)
    const prevStatus = String(rows[i][statusCol] || '');
    const activeForDist = items.filter(item => !item.cancelled);
    const allDone = activeForDist.length > 0 && activeForDist.every(item => item.distributed);
    const newStatus = allDone ? 'distributed' : 'approved';

    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, statusCol + 1).setValue(newStatus);
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    // 이메일 발송 (전체 배부완료 시)
    if (allDone) {
      const recipientEmail = rows[i][6];
      if (recipientEmail) {
        sendNotificationEmail(recipientEmail, rows[i][4], rows[i][2], rows[i][3], rows[i][7], items, 'distributed', '');
      }
      // 방금 막 배부완료로 전환된 경우(이미 배부완료 상태였던 걸 재저장한 게 아닌 경우)에만
      // 결과보고 등록 안내 메일을 즉시 발송 — 매번 다시 보내지 않도록 상태 전환 시점에만 트리거
      if (prevStatus !== 'distributed' && recipientEmail) {
        try {
          sendResultReportRequestEmail({
            email: recipientEmail, name: rows[i][4], reason: rows[i][7],
            useDate: formatDateOnly(rows[i][9])
          }, 'immediate');
        } catch (e) { Logger.log('결과보고 즉시안내 메일 발송 실패: ' + e.message); }
      }
    }

    return { ok: true, status: newStatus, deferredReqId, stockWarnings };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 신청 취소 (재고 복구) ─────────────────────────────────────
function cancelRequest({ id }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8 : 10;
    const statusCol= isOld ? 10 : 12;

    const status = String(rows[i][statusCol] || '');
    if (status === 'distributed') return { ok: false, error: '이미 배부 완료된 신청은 취소할 수 없습니다.' };
    if (status === 'cancelled')   return { ok: false, error: '이미 취소된 신청입니다.' };

    // 재고 복구
    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) {}
    items.forEach(item => restoreStock(item.num, item.qty, { reqId: id, name: rows[i][4], reason: '신청 전체취소' }));

    s.getRange(i + 1, statusCol + 1).setValue('cancelled');
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 항목별 취소 (부분취소) ────────────────────────────────────
function cancelItems({ id, indices }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8 : 10;
    const statusCol= isOld ? 10 : 12;

    const status = String(rows[i][statusCol] || '');
    if (status === 'distributed') return { ok: false, error: '배부 완료된 신청은 항목 취소가 불가합니다.' };
    if (status === 'cancelled')   return { ok: false, error: '이미 전체 취소된 신청입니다.' };

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) {}

    // 선택 항목 취소 처리 및 재고 복구
    indices.forEach(idx => {
      if (items[idx] && !items[idx].cancelled && !items[idx].distributed) {
        items[idx].cancelled = true;
        restoreStock(items[idx].num, items[idx].qty, { reqId: id, name: rows[i][4], reason: '항목 취소(관리자)' });
      }
    });

    // 전체 취소됐으면 cancelled, 나머지가 모두 승인됐으면 approved
    const activeItems  = items.filter(item => !item.cancelled);
    const allCancelled = activeItems.length === 0;
    const allApproved  = !allCancelled && activeItems.every(item => item.approved);
    let newStatus = status;
    if (allCancelled) newStatus = 'cancelled';
    else if (allApproved && status === 'pending') newStatus = 'approved';

    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, statusCol + 1).setValue(newStatus);
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    // 취소 후 나머지가 모두 승인돼서 approved로 전환 시 이메일
    if (allApproved && status === 'pending') {
      const recipientEmail = rows[i][6];
      if (recipientEmail) {
        sendNotificationEmail(recipientEmail, rows[i][4], rows[i][2], rows[i][3], rows[i][7], activeItems, 'approved', '');
      }
    }

    return { ok: true, status: newStatus };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 유저 취소신청 ────────────────────────────────────────────────
function requestCancelItem({ id, idx }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8 : 10;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) {}

    if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };
    if (items[idx].cancelled) return { ok: false, error: '이미 취소된 항목입니다.' };
    if (items[idx].distributed) return { ok: false, error: '이미 배부된 항목은 취소신청할 수 없습니다.' };

    items[idx].cancelRequested = true;
    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 관리자 취소확정 ───────────────────────────────────────────────
function confirmCancelItem({ id, idx }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8  : 10;
    const statusCol= isOld ? 10 : 12;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) {}

    if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };

    // 재고 복구 후 취소 확정
    restoreStock(items[idx].num, items[idx].qty, { reqId: id, name: rows[i][4], reason: '취소 확정(관리자)' });
    items[idx].cancelled = true;
    delete items[idx].cancelRequested;

    // 전체 취소 여부 확인
    const activeItems = items.filter(item => !item.cancelled);
    const newStatus = activeItems.length === 0 ? 'cancelled' : String(rows[i][statusCol] || '');

    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, statusCol + 1).setValue(newStatus);
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 관리자 취소신청 거절 ──────────────────────────────────────────
function rejectCancelItem({ id, idx }) {
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();

  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;

    const isOld    = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const itemsCol = isOld ? 8 : 10;

    let items = [];
    try { items = JSON.parse(rows[i][itemsCol] || '[]'); } catch(e) {}

    if (!items[idx]) return { ok: false, error: '항목을 찾을 수 없습니다.' };

    delete items[idx].cancelRequested;
    s.getRange(i + 1, itemsCol + 1).setValue(JSON.stringify(items));
    s.getRange(i + 1, (isOld ? 11 : 13) + 1).setValue(new Date().toLocaleString('ko-KR'));

    return { ok: true };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// ── 결과보고서 구글 드라이브 업로드 ─────────────────────────────
// 업로드 파일은 전용 폴더에 두고, 링크를 아는 "같은 도메인(월드비전) 로그인 사용자"만 볼 수 있게 한다.
// (예전에는 링크만 알면 누구나 볼 수 있는 공개 공유였다 — 수혜자 명단에 이름·연락처가 들어 있어 위험)
// 소유 계정이 도메인 공유를 지원하지 않으면 비공개로 저장하고 sharing:'private'로 알려준다.
function getReportFolder_() {
  const props = PropertiesService.getScriptProperties();
  const id = props.getProperty('REPORT_FOLDER_ID');
  if (id) { try { return DriveApp.getFolderById(id); } catch (e) {} }
  const folder = DriveApp.createFolder('GIK_결과보고_업로드');
  props.setProperty('REPORT_FOLDER_ID', folder.getId());
  return folder;
}
function createReportFile_(blob) {
  const file = getReportFolder_().createFile(blob);
  let sharing = 'domain';
  try {
    file.setSharing(DriveApp.Access.DOMAIN_WITH_LINK, DriveApp.Permission.VIEW);
  } catch (e) {
    sharing = 'private';
    try { file.setSharing(DriveApp.Access.PRIVATE, DriveApp.Permission.NONE); } catch (e2) {}
  }
  return { file, sharing };
}
const UPLOAD_ALLOWED_EXT = ['xlsx', 'xls', 'csv', 'pdf', 'doc', 'docx', 'pptx'];
const UPLOAD_MAX_B64_LEN = 14 * 1000 * 1000; // base64 문자 수 기준 약 10MB
function checkUpload_(label, b64, fname) {
  const name = cleanText_(String(fname || '').split(/[\\/]/).pop()).slice(0, 100);
  const ext = (name.split('.').pop() || '').toLowerCase();
  if (!name || UPLOAD_ALLOWED_EXT.indexOf(ext) < 0) {
    return { err: `${label}: 업로드할 수 없는 파일 형식입니다. (가능: ${UPLOAD_ALLOWED_EXT.join(', ')})` };
  }
  if (String(b64 || '').length > UPLOAD_MAX_B64_LEN) return { err: `${label}: 파일이 너무 큽니다. (10MB 이하)` };
  return { name, ext };
}
function uploadReport({ id, listFile, listFileName, docFile, docFileName }) {
  const links = [];
  let sharing = 'domain';
  if (listFile && listFileName) {
    const chk = checkUpload_('배부 명단 파일', listFile, listFileName);
    if (chk.err) return { ok: false, error: chk.err };
    listFileName = chk.name;
  }
  if (docFile && docFileName) {
    const chk = checkUpload_('결과보고서 파일', docFile, docFileName);
    if (chk.err) return { ok: false, error: chk.err };
    docFileName = chk.name;
  }

  if (listFile && listFileName) {
    const blob = Utilities.newBlob(Utilities.base64Decode(listFile), MimeType.MICROSOFT_EXCEL, listFileName);
    const made = createReportFile_(blob);
    if (made.sharing === 'private') sharing = 'private';
    links.push('명단: ' + made.file.getUrl());
  }

  if (docFile && docFileName) {
    const lower = String(docFileName).toLowerCase();
    const mime = lower.endsWith('.pdf') ? MimeType.PDF
      : (lower.endsWith('.xlsx') || lower.endsWith('.xls')) ? MimeType.MICROSOFT_EXCEL
      : lower.endsWith('.pptx') ? MimeType.MICROSOFT_POWERPOINT
      : MimeType.MICROSOFT_WORD;
    const blob = Utilities.newBlob(Utilities.base64Decode(docFile), mime, docFileName);
    const made = createReportFile_(blob);
    if (made.sharing === 'private') sharing = 'private';
    links.push('보고서: ' + made.file.getUrl());
  }

  if (links.length === 0) return { ok: false, error: '업로드할 파일이 없습니다.' };

  // 신청 시트의 관리자메모 칸에 링크 저장
  const s = sheet(SHEET_REQ);
  const rows = s.getDataRange().getValues();
  for (let i = 1; i < rows.length; i++) {
    if (String(rows[i][0]) !== String(id)) continue;
    const isOld   = String(rows[i][8]).trim().startsWith('[') || String(rows[i][8]).trim().startsWith('{');
    const noteCol = isOld ? 12 : 14;
    const existing = String(rows[i][noteCol] || '');
    s.getRange(i + 1, noteCol + 1).setValue(existing ? existing + '\n' + links.join('\n') : links.join('\n'));
    return { ok: true, links, sharing };
  }
  return { ok: false, error: '신청을 찾을 수 없습니다.' };
}

// 1회 실행용(메뉴 또는 편집기): 이미 올라간 결과보고 파일의 공유를 "링크 아는 누구나" → "같은 도메인 사용자"로 바꾼다.
function restrictExistingReportFiles() {
  const rows = sheet(SHEET_REQ).getDataRange().getValues().slice(1);
  const ids = {};
  rows.forEach(r => {
    [r[12], r[14]].forEach(note => {
      String(note || '').split('\n').forEach(line => {
        const m = line.match(/\/d\/([A-Za-z0-9_-]{15,})/) || line.match(/[?&]id=([A-Za-z0-9_-]{15,})/);
        if (m) ids[m[1]] = true;
      });
    });
  });
  const list = Object.keys(ids);
  let ok = 0, fail = 0;
  list.forEach(fid => {
    try { DriveApp.getFileById(fid).setSharing(DriveApp.Access.DOMAIN_WITH_LINK, DriveApp.Permission.VIEW); ok++; }
    catch (e) { fail++; Logger.log('공유 제한 실패: ' + fid + ' — ' + e.message); }
  });
  const msg = `결과보고 파일 ${list.length}개 중 ${ok}개를 도메인 공유로 제한했습니다.` + (fail ? `\n실패 ${fail}개(권한 없음/삭제됨) — 실행 로그를 확인하세요.` : '');
  Logger.log(msg);
  try { SpreadsheetApp.getUi().alert(msg); } catch (e) {}
}

